export const csaQuestionPool: CsaQuestion[] = [
  // ── csa-variables-types (primitive-types) ──
  { question: 'Which declaration compiles without an error?', options: ['int total = 4.25;', 'double rate = 4;', 'boolean done = 1;', 'int count = "four";'], correctAnswer: 1, explanation: 'An int value widens to double automatically, so rate stores 4.0. Storing the double 4.25 in an int needs an explicit cast, 1 is not a boolean value in Java, and a String literal cannot be stored in an int variable.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What value is stored in avg after this statement executes?\ndouble avg = 9 / 2;', options: ['4.5', '5.0', '4.0', '4'], correctAnswer: 2, explanation: 'Both operands are ints, so 9 / 2 is integer division and produces 4; that int is then widened to 4.0 when it is stored in the double. The value 4.5 would need a double operand, 5.0 would mean rounding, and a double variable never holds the int 4 itself.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'A variable will count how many late passes a student has used. Which identifier is legal in Java and follows the naming convention for variables?', options: ['latePassCount', 'LatePassCount', 'late-pass-count', '1stLatePass'], correctAnswer: 0, explanation: 'Variables use camelCase: lowercase first word, capitalized later words. LatePassCount is legal but uses the class-name convention, a hyphen is not allowed in an identifier, and an identifier cannot begin with a digit.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is the value of the expression (int) 8.99 ?', options: ['9.0', '8.99', '8.0', '8'], correctAnswer: 3, explanation: 'Casting a double to int truncates, dropping the fractional part without rounding, so the result is the int 8. 9.0 would require rounding and is a double, 8.99 is the uncast value, and 8.0 is a double rather than the int the cast produces.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'A class contains the declaration final int MAX_SEATS = 30; and a later statement MAX_SEATS = 32; What happens?', options: ['MAX_SEATS is changed to 32', 'MAX_SEATS silently stays 30', 'It throws an exception at run time', 'It fails to compile'], correctAnswer: 3, explanation: 'A final variable cannot be reassigned after it is initialized, and the compiler rejects the second assignment. The value never changes to 32, the reassignment is not silently ignored, and the problem is caught at compile time rather than when the program runs.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = 11;\nint b = 4;\ndouble r = (double) (a / b);\nSystem.out.println(r);', options: ['2.75', '2', '2.0', '3.0'], correctAnswer: 2, explanation: 'The parentheses make a / b run first as integer division, giving 2, and only then is 2 cast to 2.0. Getting 2.75 would require casting a before dividing, printing 2 ignores that r is a double, and 3.0 assumes rounding.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'Given int p = 5; and int q = 2; which expression evaluates to 2.5?', options: ['(double) (p / q)', '(double) p / q', 'p / q * 1.0', '(int) (p / 2.0)'], correctAnswer: 1, explanation: 'The cast applies to p alone, so 5.0 / 2 is double division and gives 2.5. Casting the whole quotient happens after integer division produces 2, multiplying by 1.0 after dividing also starts from 2, and casting 2.5 back to int truncates it to 2.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is the value of x after this statement executes?\nint x = (int) (7.9 + 2.6);', options: ['10', '9', '11', '10.5'], correctAnswer: 0, explanation: 'The sum 10.5 is computed first, and the cast then truncates it to 10. A result of 9 comes from casting each number before adding, 11 assumes the cast rounds, and 10.5 cannot be stored in an int.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'A program has a positive double variable d. Which expression rounds d to the nearest int?', options: ['(int) d + 0.5', '(int) d + 1', '(int) (d + 0.5)', 'd + (int) 0.5'], correctAnswer: 2, explanation: 'Adding 0.5 before truncating pushes values with a fractional part of 0.5 or more up to the next int, which is rounding for positive numbers. Casting d first and then adding 0.5 produces a double that was never rounded, (int) d + 1 always rounds up, and d + (int) 0.5 casts only the 0.5, which becomes 0, so d is unchanged.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint n = 17;\ndouble h = n / 5;\nint k = (int) (n / 5.0);\nSystem.out.println(h + " " + k);', options: ['3.4 3', '3.0 3', '3.0 3.4', '3 3'], correctAnswer: 1, explanation: 'n / 5 is integer division, so h stores 3.0; n / 5.0 is 3.4, and the cast truncates it to 3. Showing 3.4 for h ignores integer division, k is an int and cannot print 3.4, and h is a double, so it prints with a decimal point.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'Which statement causes a compile error?', options: ['double d = 12;', 'int n = 7 / 2;', 'double e = 7;', 'int m = 2.0 * 3;'], correctAnswer: 3, explanation: '2.0 * 3 is a double, and a double cannot be assigned to an int without an explicit cast. Assigning an int to a double widens automatically, 7 / 2 is an int expression, and storing the int 7 in a double also widens without error.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'Why does the statement int total = 3.5 + 2; fail to compile?', options: ['The double sum needs a cast to be stored in an int', 'An int and a double cannot be added in Java', 'The value 5.5 is outside the range of int', 'The literal 2 must be written as 2.0 first'], correctAnswer: 0, explanation: 'Adding an int to a double produces a double, 5.5, and narrowing a double to int requires an explicit cast. Mixed int and double arithmetic is legal, a value like 5.5 is far inside the range of int, and the 2 is promoted to double automatically.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'Which declaration stores whether a score of 85 meets a cutoff of 70?', options: ['boolean pass = "true";', 'boolean pass = 85 >= 70;', 'int pass = 85 >= 70;', 'boolean pass = 85 - 70;'], correctAnswer: 1, explanation: 'A relational expression such as 85 >= 70 evaluates to a boolean, here true, so it can be stored in a boolean variable. A String literal is not a boolean, a boolean value cannot be stored in an int, and 85 - 70 is an int, not a boolean.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint total = 50;\nint count = 4;\ndouble avg1 = total / count;\ndouble avg2 = (double) total / count;\nSystem.out.println(avg2 - avg1);', options: ['0.0', '12.5', '0.5', '0'], correctAnswer: 2, explanation: 'avg1 is 12.0 because 50 / 4 is integer division, while avg2 is 12.5 because the cast makes the division double. Their difference is 0.5. Answering 0.0 treats both as double division, 12.5 is avg2 alone, and the difference of two doubles is a double, not the int 0.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },
  { question: 'A quiz has 40 questions and a student answered 37 correctly. Given int right = 37; and int total = 40; which statement stores 92.5 in pct?', options: ['double pct = right / total * 100;', 'double pct = 100 * right / total;', 'double pct = (double) (right / total) * 100;', 'double pct = 100.0 * right / total;'], correctAnswer: 3, explanation: '100.0 * right is the double 3700.0, so dividing by total is double division and gives 92.5. Dividing right by total first gives the int 0, multiplying by the int 100 first gives 3700 / 40 = 92 as integer division, and casting after right / total still starts from 0.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 1, part: 1 },
  { question: 'What is the value of the expression (int) -3.7 ?', options: ['-3', '-4', '-3.7', '3'], correctAnswer: 0, explanation: 'Casting to int truncates toward zero, so the fractional part is dropped and -3.7 becomes -3. A result of -4 would mean rounding down, -3.7 is the uncast double, and the cast never changes the sign.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-variables-types', formSet: 2, part: 1 },

  // ── csa-expressions-operators (primitive-types) ──
  { question: 'What is the value of 125 % 12 ?', options: ['10', '12', '5', '120'], correctAnswer: 2, explanation: '125 divided by 12 is 10 with a remainder of 5, and % returns the remainder. The value 10 is the quotient, 12 is the divisor, and 120 is the largest multiple of 12 that fits into 125.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'What is the value of the expression 20 - 6 / 2 * 3 ?', options: ['21', '11', '19', '17'], correctAnswer: 1, explanation: 'Division and multiplication come before subtraction and run left to right: 6 / 2 is 3, 3 * 3 is 9, and 20 - 9 is 11. A result of 21 subtracts first, 19 multiplies 2 * 3 before dividing, and 17 drops the multiplication.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 8;\ncount += 3;\ncount--;', options: ['11', '12', '9', '10'], correctAnswer: 3, explanation: 'count += 3 raises 8 to 11, and count-- lowers it by one to 10. The value 11 ignores the decrement, 12 treats the decrement as another increment, and 9 ignores the compound assignment.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'The int variable year holds 2026. Which expression evaluates to 26?', options: ['year % 100', 'year / 100', 'year % 10', 'year / 10 % 10'], correctAnswer: 0, explanation: 'The remainder after dividing by 100 is the last two digits, 26. year / 100 gives 20, year % 10 gives only the last digit, 6, and year / 10 % 10 gives the tens digit, 2.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is printed by the following statement?\nSystem.out.println(2 + 3 + "x" + 2 + 3);', options: ['5x5', '23x23', '5x23', '23x5'], correctAnswer: 2, explanation: 'Evaluation runs left to right: 2 + 3 is int addition giving 5, then 5 + "x" becomes the String "5x", and every later + is concatenation, giving "5x23". Getting 5x5 adds the right-hand numbers as ints, and 23x23 or 23x5 concatenates the left-hand numbers before any String appears.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint n = 472;\nint sum = 0;\nsum += n % 10;\nn /= 10;\nsum += n % 10;\nn /= 10;\nsum += n;\nSystem.out.println(sum);', options: ['13', '9', '6', '2'], correctAnswer: 0, explanation: 'The segment adds the ones digit 2, then the tens digit 7, then what remains of n after two divisions, which is 4, so sum is 13. A result of 9 drops the final term, 6 skips the tens digit, and 2 counts only the ones digit.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is the value of x after this code segment executes?\nint x = 23;\nx /= 4;\nx *= 3;\nx %= 5;', options: ['3', '5', '15', '0'], correctAnswer: 3, explanation: '23 / 4 is 5 in integer division, 5 * 3 is 15, and 15 % 5 is 0. The value 15 skips the last statement, 3 treats %= as if it divided, and 5 confuses the remainder with the divisor.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = 5;\nint b = 2;\na++;\nb += a;\na -= b;\nSystem.out.println(a + " " + b);', options: ['-3 8', '-2 8', '6 8', '-2 7'], correctAnswer: 1, explanation: 'a becomes 6, then b becomes 2 + 6 = 8, then a becomes 6 - 8 = -2. Printing 6 8 skips the last statement, -3 8 forgets the increment when subtracting, and -2 7 uses the old value of a when updating b.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is printed by the following statement?\nSystem.out.println("A" + 2 * 3 + 1);', options: ['A7', 'A231', '7A', 'A61'], correctAnswer: 3, explanation: 'Multiplication runs first, giving 6; then "A" + 6 is "A6", and adding 1 concatenates to "A61". A7 wrongly adds 6 + 1 as ints after a String has appeared, A231 ignores that * comes before +, and 7A reverses the order of the pieces.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'Which condition is true exactly when the int n is a multiple of 4?', options: ['n / 4 == 0', '4 % n == 0', 'n % 4 == 0', 'n % 4 == 1'], correctAnswer: 2, explanation: 'A multiple of 4 leaves no remainder when divided by 4. n / 4 == 0 is true only for values from -3 to 3, 4 % n == 0 tests whether n divides 4, and n % 4 == 1 picks numbers one more than a multiple of 4.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'Six seats around a table are numbered 0 to 5, and s holds a seat number. Which expression gives the seat to the right of s, wrapping from seat 5 back to seat 0?', options: ['s + 1 % 6', '(s + 1) % 6', 's % 6 + 1', '(s + 1) - 6'], correctAnswer: 1, explanation: 'Adding 1 and then taking the remainder by 6 maps 5 to 0 and every other seat to the next number. Without parentheses, 1 % 6 is evaluated first, so the result is just s + 1; s % 6 + 1 gives 6 for seat 5 instead of wrapping, and (s + 1) - 6 is right only for seat 5 and negative for every other seat.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'What is the value of z after this code segment executes?\nint x = 7;\nint y = 3;\nint z = x % y * y + x / y;', options: ['5', '7', '9', '3'], correctAnswer: 0, explanation: '% and * share a precedence level and run left to right: 7 % 3 is 1, 1 * 3 is 3, and 7 / 3 is 2, so z is 5. A result of 9 computes x % (y * y) first, 3 forgets the division term, and 7 assumes the expression rebuilds x.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = 9;\nint b = 2;\nSystem.out.println(a / b + a % b + "" + a / b);', options: ['414', '5.54.5', '4.514.5', '54'], correctAnswer: 3, explanation: 'The first two terms are added as ints: 9 / 2 is 4 and 9 % 2 is 1, so they make 5. Adding "" turns 5 into a String, and the last a / b, which is 4, is concatenated to give "54". 414 treats every + as concatenation, and the two answers containing 4.5 treat int division as if it kept the decimal part.', difficulty: 'hard', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'Which code segment has the same effect on the int variable score as score = score * 2 + 1; ?', options: ['score *= 2 + 1;', 'score *= 2; score += 1;', 'score++; score *= 2;', 'score += score * 2;'], correctAnswer: 1, explanation: 'Doubling score and then adding 1 matches score * 2 + 1. score *= 2 + 1 multiplies by 3, incrementing first gives (score + 1) * 2, and score += score * 2 triples score.', difficulty: 'medium', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },
  { question: 'What is the value of the expression 8 - 6 / 2 + 5 ?', options: ['6', '0', '10', '8'], correctAnswer: 2, explanation: 'Division comes first, so 6 / 2 is 3; then subtraction and addition run left to right, 8 - 3 is 5 and 5 + 5 is 10. A result of 6 subtracts before dividing, 0 adds 3 + 5 before subtracting, and 8 divides 6 by 2 + 5, which is 0 in integer division.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 1, part: 1 },
  { question: 'Which statement increases the int variable n by exactly 1?', options: ['n++;', 'n =+ 1;', 'n + 1;', 'n += n;'], correctAnswer: 0, explanation: 'The increment operator adds 1 to n. n =+ 1 is read as n = +1, which sets n to 1, n + 1; is not a statement, so it does not compile, and n += n doubles n.', difficulty: 'easy', domain: 'primitive-types', topicSlug: 'csa-expressions-operators', formSet: 2, part: 1 },

  // ── csa-strings-objects (using-objects) ──
  { question: 'What value is returned by "planet".length() ?', options: ['5', '7', '4', '6'], correctAnswer: 3, explanation: '"planet" has six characters, p-l-a-n-e-t, and length() counts characters. The value 5 is the index of the last character, not the count, and 7 and 4 miscount the letters.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What String is returned by "keyboard".substring(3) ?', options: ['"yboard"', '"key"', '"board"', '"oard"'], correctAnswer: 2, explanation: 'The one-parameter substring starts at the given index and runs to the end; index 3 holds b, so the result is "board". "yboard" starts at index 2, "key" is the part before index 3, and "oard" starts at index 4.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What value is returned by "mississippi".indexOf("ss") ?', options: ['2', '3', '5', '-1'], correctAnswer: 0, explanation: 'indexOf returns the index of the first character of the first match. The first "ss" begins at index 2 (m is 0, i is 1). Index 5 is the start of the second "ss", 3 is the second s of the first match, and -1 would mean "ss" never appears.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'The String variable reply holds text typed by a user. Which expression is true exactly when reply holds exactly the text "yes"?', options: ['reply == "yes"', 'reply.equals("yes")', 'reply = "yes"', 'reply.length() > 2'], correctAnswer: 1, explanation: 'equals compares the characters of two Strings and returns a boolean. The == operator compares references, so it can be false for equal text, a single = is assignment, and checking for a length above 2 is also true for many other replies, such as "yep".', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nString s = "lamp";\ns.substring(1, 3);\ns = s + "s";\nSystem.out.println(s);', options: ['lamps', 'ams', 'amps', 'lam'], correctAnswer: 0, explanation: 'Strings are immutable, and the result of substring is never stored, so s is still "lamp" when "s" is appended. Printing ams or amps assumes substring changed s, and lam ignores the concatenation.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What is the sign of the value returned by "apple".compareTo("apricot") ?', options: ['Exactly zero', 'Positive', 'Negative', 'It does not compile'], correctAnswer: 2, explanation: 'The Strings match through "ap"; then p comes before r, so "apple" comes first and the result is negative. Zero would require identical Strings, a positive result would put "apple" after "apricot", and comparing two Strings with compareTo is legal.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What String does t hold after this code segment executes?\nString w = "notebook";\nString t = w.substring(4) + w.substring(0, 4);', options: ['"ebooknote"', '"booknote"', '"booknot"', '"ebooknot"'], correctAnswer: 1, explanation: 'substring(4) starts at index 4, b, giving "book", and substring(0, 4) gives indices 0 through 3, "note". "ebooknote" starts the first piece at index 3, and the versions ending in "not" stop the second piece one character early, at index 2.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString s = "banana";\nint i = s.indexOf("n");\ns = s.substring(i + 1);\nSystem.out.println(s.indexOf("n"));', options: ['2', '4', '-1', '1'], correctAnswer: 3, explanation: 'The first "n" is at index 2, so s becomes "banana".substring(3), which is "ana", and the "n" in "ana" is at index 1. Answer 2 repeats the first search, 4 is the second "n" in the original String, and -1 forgets that "ana" still contains an "n".', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nString a = "plum";\nString b = "pear";\nif (a.compareTo(b) > 0) {\n    System.out.println(a);\n} else {\n    System.out.println(b);\n}', options: ['pear', 'plum', 'plumpear', 'pearplum'], correctAnswer: 1, explanation: 'Both words start with p; the next letters are l and e, and l comes after e, so a.compareTo(b) is positive and a is printed. Printing pear assumes the comparison is negative, and only one branch of an if-else runs, so the two words are never both printed.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString s = "summer";\nSystem.out.println(s.substring(s.length() - 3));', options: ['mer', 'mmer', 'er', 'sum'], correctAnswer: 0, explanation: 's.length() is 6, so the call is substring(3), which starts at the second m and gives "mer". "mmer" starts at index 2, "er" starts at index 4, and "sum" is the first three characters rather than the last three.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What happens when the call "cat".substring(1, 4) executes?', options: ['It returns "at"', 'It returns "cat"', 'It returns ""', 'It throws an exception'], correctAnswer: 3, explanation: '"cat" has length 3, so the largest legal end index is 3; an end index of 4 throws a StringIndexOutOfBoundsException at run time. Returning "at" assumes Java trims the end index, "cat" ignores the start index, and an empty string is returned only when the start and end indexes are equal.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nString s = "abcabcab";\nint count = 0;\nint pos = s.indexOf("ab");\nwhile (pos >= 0) {\n    count++;\n    s = s.substring(pos + 2);\n    pos = s.indexOf("ab");\n}', options: ['2', '4', '3', '8'], correctAnswer: 2, explanation: 'The first match is at 0, leaving "cabcab"; the next is at 1, leaving "cab"; the next is at 1, leaving "", where indexOf returns -1. That is three matches. A count of 2 misses the "ab" at the very end, 4 counts a match that is not there, and 8 is the length of the String.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'Which of the following expressions evaluates to true?', options: ['"car".compareTo("cart") < 0', '"dog".compareTo("cat") < 0', '"pen".compareTo("pen") < 0', '"tap".compareTo("tan") < 0'], correctAnswer: 0, explanation: 'When one String is a prefix of the other, the shorter String comes first, so "car" before "cart" gives a negative result. "dog" comes after "cat" because d follows c, equal Strings compare as 0, and "tap" comes after "tan" because p follows n.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString s = "data";\nSystem.out.println(s.length() + s.substring(2));', options: ['4da', '4at', 'ta4', '4ta'], correctAnswer: 3, explanation: 's.length() is the int 4, and adding it to the String "ta" concatenates, giving "4ta". "4da" starts the substring at index 1, "4at" reverses the characters, and "ta4" reverses the order of the two operands.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },
  { question: 'What value is returned by "cloud".indexOf("z") ?', options: ['0', '5', '-1', 'null'], correctAnswer: 2, explanation: 'indexOf returns -1 when the search text never appears. 0 is the index of the first character, 5 is the length of the String, and indexOf returns an int, so it can never return null.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 1, part: 1 },
  { question: 'For a String s and int values a and b with 0 <= a <= b <= s.length(), how many characters does s.substring(a, b) contain?', options: ['b - a + 1', 'b - a', 'b - a - 1', 's.length() - a'], correctAnswer: 1, explanation: 'The substring includes index a and stops just before index b, so it holds b - a characters. Adding 1 treats index b as included, subtracting 1 excludes index a too, and s.length() - a is the length of s.substring(a), which runs to the end of the String.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-strings-objects', formSet: 2, part: 1 },

  // ── csa-using-objects (using-objects) ──
  { question: 'What is printed by the following statement?\nSystem.out.println(Math.pow(2, 4));', options: ['16', '8.0', '16.0', '6.0'], correctAnswer: 2, explanation: 'Math.pow returns a double, and 2 raised to the 4th power is 16, so 16.0 is printed. Printing 16 ignores the double return type, 8.0 multiplies 2 by 4, and 6.0 adds them.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following statement?\nSystem.out.println(Math.sqrt(49) + Math.abs(-3));', options: ['4.0', '10.0', '10', '7.0'], correctAnswer: 1, explanation: 'Math.sqrt(49) is the double 7.0 and Math.abs(-3) is 3, so the sum is the double 10.0. A result of 4.0 subtracts instead of adding the absolute value, 10 ignores that sqrt returns a double, and 7.0 leaves out the Math.abs term.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'The Ticket class has one constructor, public Ticket(String event, double price). Which statement compiles?', options: ['Ticket t = new Ticket(25, "Jazz");', 'Ticket t = Ticket("Jazz", 25.0);', 'Ticket t = new Ticket("Jazz");', 'Ticket t = new Ticket("Jazz", 25.0);'], correctAnswer: 3, explanation: 'The arguments must match the constructor\'s parameter list in number, type, and order, and new is required to create the object. Swapping the arguments mismatches the types, leaving out new is not a constructor call, and there is no one-parameter constructor.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'A program declares String title = null; Which statement throws a NullPointerException when it executes?', options: ['int n = title.length();', 'String t = title;', 'title = "Dune";', 'boolean b = (title == null);'], correctAnswer: 0, explanation: 'Calling a method on a null reference throws a NullPointerException because there is no object to run length() on. Copying a null reference, assigning a new String to the variable, and comparing a reference with null using == are all legal.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'Which of the following is a call to a static (class) method?', options: ['Math.abs(-4)', 'word.length()', 'text.length()', 'name.substring(1)'], correctAnswer: 0, explanation: 'Math.abs is called on the class name Math, which is how class methods are called. The other calls are made on objects, word, text, and name, so they are instance methods.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint[] a = {4, 5, 6};\nint[] b = a;\nb[1] = 9;\na = new int[] {1, 2, 3};\nSystem.out.println(b[1] + a[1]);', options: ['7', '11', '18', '14'], correctAnswer: 1, explanation: 'b and a start as aliases, so b[1] = 9 changes the shared array. Then a is pointed at a new array, but b still refers to the original {4, 9, 6}, so the sum is 9 + 2 = 11. A result of 7 ignores the aliasing, 18 assumes a still refers to the old array, and 14 adds the original 5 to 9.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint x = 5;\nint y = x;\ny += 3;\nSystem.out.println(x + " " + y);', options: ['8 8', '5 5', '5 8', '8 5'], correctAnswer: 2, explanation: 'Assigning one int to another copies the value, so changing y has no effect on x. Printing 8 8 treats the primitives as aliases, 5 5 ignores the update to y, and 8 5 applies the update to the wrong variable.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'Which expression produces a random int from 10 to 20, inclusive, with each value equally likely?', options: ['(int) (Math.random() * 10) + 10', '(int) (Math.random() * 20) + 10', '(int) (Math.random() * 11 + 9)', '(int) (Math.random() * 11) + 10'], correctAnswer: 3, explanation: 'The range 10 to 20 holds 11 values, so multiplying by 11 and truncating gives 0 to 10, and adding 10 shifts that to 10 to 20. Multiplying by 10 can never produce 20, multiplying by 20 reaches 29, and adding 9 gives 9 to 19.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'What are the smallest and largest values the expression (int) (Math.random() * 6) + 5 can produce?', options: ['5 and 10', '5 and 11', '0 and 5', '6 and 11'], correctAnswer: 0, explanation: 'Math.random() * 6 ranges from 0.0 up to but not including 6.0, so truncating gives 0 through 5, and adding 5 gives 5 through 10. Reaching 11 would require Math.random() to return 1.0, 0 and 5 forgets the + 5, and 6 and 11 assumes the cast rounds up.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString p = "red";\nString q = p;\np = p + "dish";\nSystem.out.println(q + " " + p);', options: ['reddish reddish', 'red red', 'reddish red', 'red reddish'], correctAnswer: 3, explanation: 'p + "dish" creates a new String, and p is pointed at it; q still refers to the original "red" because Strings are immutable. Printing reddish twice assumes q follows p, red red ignores the reassignment of p, and reddish red swaps the two.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'The class Circle contains the method public static double area(double r). Which statement calls it correctly and stores its result?', options: ['double a = new Circle.area(2.5);', 'double a = Circle.area(double 2.5);', 'double a = Circle.area(2.5);', 'double a = Circle.area("2.5");'], correctAnswer: 2, explanation: 'A static method is called with the class name, a dot, and the method name, and its double result can be stored in a double variable. new is used only to call a constructor, an argument is written without a type, and the String "2.5" does not match the double parameter.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'What is printed by the following statement?\nSystem.out.println(Math.abs(3 - 8) + Math.sqrt(16) * 2);', options: ['18.0', '13.0', '13', '9.0'], correctAnswer: 1, explanation: 'Math.abs(3 - 8) is 5 and Math.sqrt(16) is 4.0; multiplication runs before addition, so the result is 5 + 8.0 = 13.0, a double. A result of 18.0 adds before multiplying, 13 ignores that sqrt returns a double, and 9.0 drops the multiplication.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'After the statements Lamp a = new Lamp(); and Lamp b = a; execute, how many Lamp objects exist, and how are they referenced?', options: ['Two objects, one for each variable', 'Two objects, with b a copy of a', 'One object, shared by a and b', 'No object until a method is called'], correctAnswer: 2, explanation: 'new runs once, so one object exists; assigning a to b copies the reference, making a and b aliases. Assigning a reference never creates a second object, and the object exists as soon as new returns, before any method call.', difficulty: 'medium', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },
  { question: 'Which values can the expression (int) Math.random() * 6 produce?', options: ['0 through 5', 'Only 0', '1 through 6', '0 through 6'], correctAnswer: 1, explanation: 'The cast applies only to Math.random(), which is always less than 1.0, so it truncates to 0 and 0 * 6 is always 0. Getting 0 through 5 needs parentheses around Math.random() * 6 before the cast, and the other ranges also misplace the cast.', difficulty: 'hard', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 2, part: 1 },
  { question: 'What does the keyword new do when it is used as in new Lamp() ?', options: ['It creates an object and runs a constructor', 'It declares a variable without making an object', 'It copies an existing object into a variable', 'It calls a static method that belongs to Lamp'], correctAnswer: 0, explanation: 'new allocates a new object, runs the matching constructor to initialize it, and returns a reference to it. Declaring a variable does not need new, new never copies an existing object, and a constructor is not a static method call.', difficulty: 'easy', domain: 'using-objects', topicSlug: 'csa-using-objects', formSet: 1, part: 1 },

  // ── csa-boolean-if (conditionals) ──
  { question: 'Given int a = 4; and int b = 9; which expression evaluates to true?', options: ['b > a && a > 5', '!(b > a)', 'a == b - 4', 'a > b || b < 10'], correctAnswer: 3, explanation: 'a > b is false, but b < 10 is true, and || needs only one true side. In b > a && a > 5 the second side is false, so the && is false, !(b > a) negates a true comparison, and b - 4 is 5, which does not equal 4.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint t = 72;\nif (t >= 90) {\n    System.out.print("hot");\n} else if (t >= 70) {\n    System.out.print("warm");\n} else if (t >= 50) {\n    System.out.print("mild");\n} else {\n    System.out.print("cold");\n}', options: ['warmmild', 'mild', 'warm', 'cold'], correctAnswer: 2, explanation: 'The first condition is false, and t >= 70 is the first true condition, so "warm" prints and the rest of the chain is skipped. Only one branch of an if-else-if chain runs, so "mild" is never added even though t >= 50 is also true.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'Which expression is equivalent to !(x >= 10) for every int x?', options: ['x <= 10', 'x > 10', 'x != 10', 'x < 10'], correctAnswer: 3, explanation: 'The opposite of "at least 10" is "less than 10". x <= 10 is wrongly true when x is 10, x > 10 is the wrong direction, and x != 10 is wrongly true for values above 10.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'rain and cold are boolean variables. Which expression is equivalent to !(rain || cold)?', options: ['!rain && !cold', '!rain || !cold', 'rain && cold', '!rain && cold'], correctAnswer: 0, explanation: 'By De Morgan\'s law, negating an OR negates each part and changes || to &&. Keeping || after negating each part gives a different result, rain && cold negates nothing, and !rain && cold negates only one part.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'The int variables count and total both hold 0. How is the condition count != 0 && total / count > 5 evaluated?', options: ['It is true, and no division occurs', 'It is false, and no division occurs', 'It throws an ArithmeticException', 'It divides by zero and gives 0'], correctAnswer: 1, explanation: 'count != 0 is false, and && short-circuits, so the right side, which would divide by zero, is never evaluated. A false left side makes the whole && false, not true, and the division never runs, so no exception occurs and no value is computed.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString s1 = "rock";\nString s2 = s1.substring(0, 2) + "ck";\nif (s1.equals(s2)) {\n    System.out.print("A");\n}\nif (s1 == s2) {\n    System.out.print("B");\n}', options: ['A only', 'B only', 'A and B', 'Neither'], correctAnswer: 0, explanation: 's2 is built at run time as a new String object whose characters, "rock", match s1, so equals returns true. The == operator compares references, and s1 and s2 refer to different objects, so it is false. Choosing B assumes == compares text, and the other outcomes ignore one of the two tests.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'For which value of the int x does (x > 2 && x < 5) || x == 6 evaluate to false?', options: ['3', '4', '6', '5'], correctAnswer: 3, explanation: 'For x = 5, x < 5 is false, so the && part is false, and x == 6 is also false. For 3 and 4 the && part is true, and for 6 the right side of || is true.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint n = 15;\nString out = "";\nif (n % 3 == 0) {\n    out += "F";\n}\nif (n % 5 == 0) {\n    out += "B";\n} else {\n    out += "X";\n}\nSystem.out.println(out);', options: ['F', 'FBX', 'FB', 'FX'], correctAnswer: 2, explanation: 'The two if statements are separate, so both run: 15 % 3 is 0, adding "F", and 15 % 5 is 0, adding "B". The else belongs only to the second if and is skipped because its condition is true.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'What is the value of grade after this code segment executes?\nint score = 85;\nString grade = "F";\nif (score >= 60) {\n    grade = "D";\n} else if (score >= 70) {\n    grade = "C";\n} else if (score >= 80) {\n    grade = "B";\n}', options: ['"B"', '"D"', '"C"', '"F"'], correctAnswer: 1, explanation: 'The first condition, score >= 60, is already true for 85, so grade becomes "D" and the rest of the chain is skipped. The conditions are in the wrong order for a grading scale, which is why the more specific "B" is never reached; "F" would remain only if no condition were true.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'Which expression is equivalent to !(age < 13 || age > 19) ?', options: ['age > 13 || age < 19', 'age > 13 && age < 19', 'age >= 13 && age <= 19', 'age < 13 && age > 19'], correctAnswer: 2, explanation: 'De Morgan\'s law turns the negated OR into an AND of the negated parts: age >= 13 and age <= 19. Joining the bounds with || makes the expression true for every age, using > and < leaves out 13 and 19, and the last expression is never true.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = 0;\nint b = 5;\nif (a != 0 && b / a > 1) {\n    b = 1;\n} else if (a == 0 || b / a > 1) {\n    b = 2;\n}\nSystem.out.println(b);', options: ['1', '5', 'An ArithmeticException', '2'], correctAnswer: 3, explanation: 'In the first condition a != 0 is false, so && skips the division and the condition is false. In the second, a == 0 is true, so || skips the division and b becomes 2. Short-circuiting means no division by zero ever happens, and the first branch never runs.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'Which expression is true exactly when the int n is outside the range 1 to 10, inclusive?', options: ['n < 1 || n > 10', 'n <= 0 && n >= 11', 'n <= 1 || n >= 10', '!(n > 1 && n < 10)'], correctAnswer: 0, explanation: 'A value is outside the range when it is below 1 or above 10. No number is both at most 0 and at least 11, and the other two expressions wrongly count 1 and 10 as outside the range.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'Which operator tests whether two int values are not equal?', options: ['=!', '!=', '<>', '!=='], correctAnswer: 1, explanation: 'In Java, != is the not-equal operator. The other symbols are not Java comparison operators, so code that uses them does not compile.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint x = 3;\nint y = 8;\nif (x > y || y % x == 2) {\n    x += y;\n}\nif (x > y) {\n    y = x - y;\n}\nSystem.out.println(x + " " + y);', options: ['11 3', '11 8', '3 8', '3 5'], correctAnswer: 0, explanation: 'x > y is false, but 8 % 3 is 2, so the first condition is true and x becomes 11. Now x > y, so y becomes 11 - 8 = 3. Printing 11 8 skips the second if, and the outputs starting with 3 assume the first condition was false.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 2, part: 1 },
  { question: 'Which statement prints even only when the int n is even?', options: ['if (n / 2 == 0) System.out.println("even");', 'if (n % 2 == 0) System.out.println("even");', 'if (n % 2 == 1) System.out.println("even");', 'if (n % 2 = 0) System.out.println("even");'], correctAnswer: 1, explanation: 'An even number leaves remainder 0 when divided by 2. n / 2 == 0 is true only for -1, 0, and 1, n % 2 == 1 detects positive odd numbers, and a single = is assignment, which does not compile in a condition.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-boolean-if', formSet: 1, part: 1 },

  // ── csa-conditionals (conditionals) ──
  { question: 'What is printed by the following code segment?\nint hour = 14;\nboolean weekend = false;\nif (hour >= 12) {\n    if (weekend) {\n        System.out.println("relax");\n    } else {\n        System.out.println("noon");\n    }\n} else {\n    System.out.println("early");\n}', options: ['relax', 'early', 'Nothing is printed', 'noon'], correctAnswer: 3, explanation: 'hour >= 12 is true, so the outer body runs; weekend is false, so the inner else prints "noon". "relax" needs weekend to be true, "early" needs the outer condition to be false, and one of the inner branches always runs once the outer condition is true.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'In a method that returns a boolean, a and b are int variables. Which statement is equivalent to the following code segment?\nif (a == b) {\n    return false;\n} else {\n    return true;\n}', options: ['return a == b;', 'return false;', 'return a != b;', 'return !a == b;'], correctAnswer: 2, explanation: 'The method returns true exactly when a and b differ, which is the value of a != b. return a == b gives the opposite result, return false ignores the else branch, and !a is not legal when a is an int, so the last statement does not compile.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint vol = 14;\nif (vol > 10) {\n    vol = 10;\n} else if (vol < 0) {\n    vol = 0;\n}\nSystem.out.println(vol);', options: ['14', '0', '10', '4'], correctAnswer: 2, explanation: '14 is above 10, so the first branch clamps vol to 10 and the else-if is skipped. Printing 14 ignores the clamp, 0 would need vol to be negative, and 4 is the amount above the limit, not the stored value.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'A student writes the condition if (0 <= t <= 100) to check whether the int t is from 0 to 100. What happens?', options: ['It works as a range check', 'It is true for every t', 'It is false for every t', 'It fails to compile'], correctAnswer: 3, explanation: '0 <= t produces a boolean, and Java cannot compare a boolean to 100 with <=, so the code does not compile. A range check must be written as 0 <= t && t <= 100, and since the code never compiles, it is never evaluated as true or false.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = 5;\nint b = -2;\nif (a > 0)\n    if (b > 0)\n        System.out.print("P");\n    else\n        System.out.print("Q");\nSystem.out.print("R");', options: ['R', 'QR', 'PR', 'Q'], correctAnswer: 1, explanation: 'Without braces, the else pairs with the nearest unmatched if, which is if (b > 0). a > 0 is true and b > 0 is false, so "Q" prints, and the last statement is outside both ifs, so "R" always prints. Printing only R pairs the else with the outer if, PR ignores that b is negative, and Q forgets the final statement.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint a = -1;\nint b = 3;\nif (a > 0) {\n    if (b > 0) {\n        System.out.print("P");\n    }\n} else {\n    System.out.print("Q");\n}\nSystem.out.print("R");', options: ['QR', 'R', 'PR', 'PQR'], correctAnswer: 0, explanation: 'The braces close the outer if body before the else, so this else belongs to the outer if (a > 0). a is negative, so "Q" prints, followed by "R". Printing only R treats the else as belonging to the inner if, PR needs a to be positive, and an if and its else never both run.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'A student tries to store the largest of three values in m. What is the value of m after this code segment executes?\nint a = 7;\nint b = 12;\nint c = 9;\nint m = a;\nif (b > a) {\n    m = b;\n}\nif (c > a) {\n    m = c;\n}', options: ['9', '12', '7', '16'], correctAnswer: 0, explanation: 'Both conditions compare against a rather than against the current m: b > a sets m to 12, and then c > a, 9 > 7, overwrites m with 9. Getting 12 requires comparing c with m, 7 ignores both updates, and 16 is the sum of a and c, which no statement stores.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'Which statement assigns to d the distance between the int values p and q, which is never negative?', options: ['int d = Math.abs(p) - Math.abs(q);', 'int d = Math.abs(p - q);', 'int d = p - q;', 'int d = Math.abs(p) + q;'], correctAnswer: 1, explanation: 'The absolute value of the difference is the distance, whichever value is larger. Subtracting the absolute values can be negative or wrong when the signs differ, p - q is negative when q is larger, and adding q is not a distance at all.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'Consider the following method. Which expression has the same value as check(n) for every int n?\npublic static boolean check(int n) {\n    if (n % 2 == 0) {\n        if (n > 10) {\n            return true;\n        }\n    }\n    return false;\n}', options: ['n % 2 == 0 || n > 10', 'n % 2 != 0 && n > 10', 'n > 10', 'n % 2 == 0 && n > 10'], correctAnswer: 3, explanation: 'The method returns true only when both nested conditions hold, which is the && of the two tests. Using || would also accept 4 or 13, testing for odd numbers flips the first condition, and n > 10 alone would also accept 13.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'What is the value of s after this code segment executes?\nint temp = 45;\nboolean wind = true;\nString s;\nif (temp < 50) {\n    if (wind) {\n        s = "coat";\n    } else {\n        s = "jacket";\n    }\n} else if (temp < 70) {\n    s = "sweater";\n} else {\n    s = "tee";\n}', options: ['"jacket"', '"sweater"', '"coat"', '"tee"'], correctAnswer: 2, explanation: 'temp < 50 is true and wind is true, so s is "coat". "jacket" needs wind to be false, and the else-if and else branches are skipped once the first condition is true.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'The int variable bonus currently holds 25. Which code segment sets bonus to 50 when sales is over 1000 and years is at least 2, and sets bonus to 0 in every other case?', options: ['if (sales > 1000 || years >= 2) { bonus = 50; } else bonus = 0;', 'if (sales > 1000) { if (years >= 2) bonus = 50; } else bonus = 0;', 'if (sales > 1000 && years >= 2) bonus = 50; else bonus = 0;', 'if (sales > 1000) bonus = 50; else if (years >= 2) bonus = 0;'], correctAnswer: 2, explanation: 'Both requirements must hold for 50, and every other case falls to the else. Using || pays 50 when only one requirement holds, the nested version leaves bonus at 25 when sales is high but years is low, and the last version pays 50 on sales alone.', difficulty: 'hard', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint x = -4;\nif (x >= 0) {\n    System.out.print("A");\n}\nif (x > -5) {\n    System.out.print("B");\n} else {\n    System.out.print("C");\n}', options: ['B', 'AB', 'BC', 'AC'], correctAnswer: 0, explanation: 'x >= 0 is false, so "A" is skipped; -4 > -5 is true, so "B" prints and its else is skipped. AB ignores the first condition, BC runs both branches of one if-else, and AC gets both comparisons backward.', difficulty: 'easy', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'Which condition is true for every int value of n?', options: ['n > 5 && n <= 5', 'n > 5 || n < 5', 'n > 4 && n < 6', 'n > 5 || n <= 5'], correctAnswer: 3, explanation: 'Every int is either greater than 5 or at most 5, so the OR is always true. The first && version is never true, n > 5 || n < 5 is false when n is 5, and n > 4 && n < 6 is true only when n is 5.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'Consider the following method. What does size(100) return?\npublic static String size(int n) {\n    if (n > 100) {\n        return "big";\n    }\n    if (n > 10) {\n        return "mid";\n    }\n    return "small";\n}', options: ['"big"', '"mid"', '"small"', '"midsmall"'], correctAnswer: 1, explanation: '100 > 100 is false, so the method moves on; 100 > 10 is true, so it returns "mid", and a return ends the method at once. "big" needs a value above 100, "small" is reached only when both tests fail, and a method returns a single value.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint x = 12;\nint y = 5;\nif (x > y) {\n    x -= y;\n    if (x > y) {\n        x -= y;\n    } else {\n        y -= x;\n    }\n} else {\n    y -= x;\n}\nSystem.out.println(x + " " + y);', options: ['7 5', '7 -2', '2 3', '2 5'], correctAnswer: 3, explanation: '12 > 5, so x becomes 7; then 7 > 5, so x becomes 2, and the inner else is skipped. Printing 7 5 stops after the first subtraction, 7 -2 runs the inner else instead, and 2 3 runs both inner branches.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 1, part: 1 },
  { question: 'The int variable max has been declared and holds 0. Which code segment stores the larger of the int values a and b in max?', options: ['if (a > b) { max = b; } else { max = a; }', 'if (a > b) { max = a; }', 'if (a >= b) { max = a; } else { max = b; }', 'max = a; if (a > b) max = b;'], correctAnswer: 2, explanation: 'Whichever value is at least as large as the other is stored, and the else covers every remaining case. Swapping the assignments stores the smaller value, the segment without an else leaves max at 0 whenever b is larger, and the last segment replaces a with b exactly when b is the smaller one.', difficulty: 'medium', domain: 'conditionals', topicSlug: 'csa-conditionals', formSet: 2, part: 1 },

  // ── csa-iteration (iteration) ──
  { question: 'How many times does the body of this loop execute?\nfor (int i = 2; i < 20; i += 2) {\n    System.out.println(i);\n}', options: ['9', '10', '18', '20'], correctAnswer: 0, explanation: 'i takes the values 2, 4, 6, and so on up to 18, which is 9 values; when i reaches 20 the condition fails. Ten also counts 20, 18 counts every int from 2 to 19 as though i increased by 1, and 20 is the loop\'s bound, not its count.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint n = 1;\nwhile (n < 50) {\n    n *= 3;\n}\nSystem.out.println(n);', options: ['27', '81', '50', '243'], correctAnswer: 1, explanation: 'n goes 1, 3, 9, 27, 81; 27 < 50 is still true, so the loop runs once more, and 81 < 50 is false, ending the loop. Printing 27 stops one step early, 50 is the bound rather than a value n ever holds, and 243 runs one step too many.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'Which of the following loops never terminates?', options: ['int k = 9; while (k > 0) { k -= 3; }', 'int k = 0; while (k != 5) { k += 2; }', 'int k = 1; while (k < 9) { k *= 2; }', 'int k = 20; while (k >= 0) { k--; }'], correctAnswer: 1, explanation: 'k takes only even values 0, 2, 4, 6, and so on, so it skips past 5 and k != 5 stays true forever. The other loops all move k toward a value that makes their conditions false: down to 0, up to 16, and down to -1.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is the value of sum after this code segment executes?\nint sum = 0;\nfor (int i = 2; i <= 8; i += 2) {\n    sum += i;\n}', options: ['20', '12', '35', '8'], correctAnswer: 0, explanation: 'The loop adds 2, 4, 6, and 8, because <= includes 8, for a total of 20. A sum of 12 stops before 8, 35 adds every int from 2 to 8, and 8 is just the last value added.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'Which code segment prints the same output as the following loop?\nfor (int i = 0; i < 4; i++) {\n    System.out.print(i);\n}', options: ['int i = -1; while (i < 4) { i++; System.out.print(i); }', 'int i = 0; while (i <= 4) { System.out.print(i); i++; }', 'int i = 0; while (i < 4) { System.out.print(i); i++; }', 'int i = 1; while (i <= 4) { System.out.print(i); i++; }'], correctAnswer: 2, explanation: 'The for loop prints 0123: it initializes i, tests the condition, runs the body, and then updates i. Starting at -1 and updating before printing gives 01234, using <= from 0 also prints 4, and running from 1 to 4 prints 1234.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nString s = "occurrence";\nint c = 0;\nfor (int i = 0; i < s.length(); i++) {\n    if (s.substring(i, i + 1).equals("c")) {\n        c++;\n    }\n}', options: ['2', '4', '1', '3'], correctAnswer: 3, explanation: 'The loop checks each one-character substring, and "c" appears at indexes 1, 2, and 8 of "occurrence". A count of 2 misses the c near the end, 4 counts a character that is not a c, and 1 counts only the first match.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'What happens when the following code segment executes?\nString s = "ab";\nfor (int i = 0; i <= s.length(); i++) {\n    System.out.print(s.substring(i, i + 1));\n}', options: ['It prints ab and then ends normally', 'It prints ab and then throws an exception', 'It prints only a and then ends normally', 'It throws an exception before printing'], correctAnswer: 1, explanation: 'For i = 0 and i = 1 the loop prints "a" and "b". The <= lets i reach 2, and substring(2, 3) on a String of length 2 throws a StringIndexOutOfBoundsException. The loop does not end normally, and nothing goes wrong until the third pass.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is the value of big after this code segment executes?\nint n = 5927;\nint big = 0;\nwhile (n > 0) {\n    int d = n % 10;\n    if (d > big) {\n        big = d;\n    }\n    n /= 10;\n}', options: ['7', '5', '9', '23'], correctAnswer: 2, explanation: 'The loop examines the digits from the right, 7, 2, 9, and 5, and keeps the largest, 9. The value 7 is only the first digit examined, 5 is the leading digit, and 23 is the sum of the digits rather than the largest one.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'What is the value of r after this code segment executes?\nString w = "stop";\nString r = "";\nfor (int i = w.length() - 1; i >= 1; i--) {\n    r += w.substring(i, i + 1);\n}', options: ['"pots"', '"stop"', '"tops"', '"pot"'], correctAnswer: 3, explanation: 'i runs 3, 2, 1, appending p, o, and t, so r is "pot". The condition i >= 1 stops before index 0, so the s is never added; "pots" would need i >= 0, "stop" is a left-to-right traversal, and "tops" adds the s first.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 0;\nint x = 100;\nwhile (x > 1) {\n    x /= 2;\n    count++;\n}', options: ['6', '7', '5', '50'], correctAnswer: 0, explanation: 'x goes 50, 25, 12, 6, 3, 1, so the body runs 6 times before x > 1 becomes false. Seven counts one extra pass, five stops at 3, and 50 is the value of x after the first pass.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'How many times does the body of this loop execute?\nfor (int i = 1; i < 100; i *= 3) {\n    System.out.println(i);\n}', options: ['33', '5', '81', '243'], correctAnswer: 1, explanation: 'i takes the values 1, 3, 9, 27, and 81; the next value, 243, fails the condition, so the body runs 5 times. 33 assumes i increases by 3 each time, 81 is the last value of i inside the loop, and 243 is the value that ends the loop, not a count.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is the value of p after this code segment executes?\nint p = 1;\nfor (int k = 5; k > 2; k--) {\n    p *= k;\n}', options: ['120', '20', '12', '60'], correctAnswer: 3, explanation: 'k takes the values 5, 4, and 3, so p is 5 * 4 * 3 = 60. 120 also multiplies by 2 and 1, 20 stops after 4, and 12 multiplies only 4 and 3.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nfor (int j = 10; j > 0; j -= 4) {\n    System.out.print(j + " ");\n}', options: ['10 6 2 -2', '6 2', '10 6 2', '10 6'], correctAnswer: 2, explanation: 'j starts at 10 and drops by 4 while it stays positive, printing 10, 6, and 2; the next value, -2, fails j > 0. Printing -2 ignores the condition, and the shorter outputs drop either the first or the last value.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint sum = 0;\nint i = 1;\nwhile (sum < 20) {\n    sum += i;\n    i += 2;\n}\nSystem.out.println(i);', options: ['11', '9', '25', '13'], correctAnswer: 0, explanation: 'sum becomes 1, 4, 9, 16, and 25 while i becomes 3, 5, 7, 9, and 11. Once sum is 25 the loop stops, and i is 11. Printing 9 forgets that i is updated after the last addition, 25 is sum rather than i, and 13 runs one extra pass.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 2, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 0;\nfor (int k = 1; k <= 30; k++) {\n    if (k % 4 == 0 || k % 6 == 0) {\n        count++;\n    }\n}', options: ['10', '2', '5', '7'], correctAnswer: 0, explanation: 'There are 7 multiples of 4 and 5 multiples of 6 from 1 to 30, but 12 and 24 are both, and || counts them once: 7 + 5 - 2 = 10. Two counts only the numbers that are multiples of both, as && would, while 5 and 7 count only one kind of multiple.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-iteration', formSet: 1, part: 1 },

  // ── csa-loops (iteration) ──
  { question: 'How many times is count++ executed by the following code segment?\nint count = 0;\nfor (int i = 0; i < 5; i++) {\n    for (int j = 0; j < 3; j++) {\n        count++;\n    }\n}', options: ['8', '5', '3', '15'], correctAnswer: 3, explanation: 'The inner loop runs 3 times for each of the 5 outer iterations, so the inner body runs 5 * 3 = 15 times. Eight adds the counts instead of multiplying, 5 counts only the outer iterations, and 3 counts only one pass of the inner loop.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 0;\nfor (int i = 0; i < 5; i++) {\n    for (int j = i; j < 5; j++) {\n        count++;\n    }\n}', options: ['25', '10', '15', '5'], correctAnswer: 2, explanation: 'The inner loop starts at i, so it runs 5, 4, 3, 2, and 1 times, for a total of 15. A count of 25 ignores that the inner start depends on i, 10 starts the inner loop at i + 1, and 5 counts only the outer iterations.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nfor (int r = 1; r <= 3; r++) {\n    for (int c = r; c <= 3; c++) {\n        System.out.print(c);\n    }\n    System.out.println();\n}', options: ['1, then 12, then 123', '123, then 23, then 3', '123, then 123, then 123', '3, then 23, then 123'], correctAnswer: 1, explanation: 'Each row starts printing at the row number and stops at 3: row 1 prints 123, row 2 prints 23, and row 3 prints 3. A growing pattern would need c to run from 1 to r, identical rows would need c to start at 1, and the reversed order lists the rows bottom to top.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'Consider the following method. What does mystery("bookkeeper") return?\npublic static int mystery(String s) {\n    int n = 0;\n    for (int i = 0; i < s.length() - 1; i++) {\n        if (s.substring(i, i + 1).equals(s.substring(i + 1, i + 2))) {\n            n++;\n        }\n    }\n    return n;\n}', options: ['3', '4', '2', '6'], correctAnswer: 0, explanation: 'The method counts adjacent pairs of equal characters: oo, kk, and ee in "bookkeeper", so it returns 3. Four counts a pair that is not adjacent, 2 misses one of the doubled letters, and 6 counts each doubled letter twice.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'Successive calls to getNext() return 8, 3, 5, -1, and 9, in that order. What is the value of sum after this code segment executes?\nint sum = 0;\nint v = getNext();\nwhile (v != -1) {\n    sum += v;\n    v = getNext();\n}', options: ['15', '25', '16', '24'], correctAnswer: 2, explanation: 'The sentinel -1 stops the loop, so only 8, 3, and 5 are added, giving 16. A sum of 15 also adds -1, 25 keeps reading past the sentinel to add 9, and 24 adds both -1 and 9.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 0;\nfor (int i = 1; i <= 3; i++) {\n    for (int j = 0; j < i * 2; j++) {\n        count++;\n    }\n}', options: ['9', '18', '6', '12'], correctAnswer: 3, explanation: 'The inner loop runs 2, 4, and 6 times for i = 1, 2, and 3, which totals 12. Nine uses i instead of i * 2 and adds 3, 18 treats every inner loop as running 6 times, and 6 counts only the last outer iteration.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'What is the value of count after this code segment executes?\nint count = 0;\nfor (int a = 1; a <= 4; a++) {\n    for (int b = 1; b <= 4; b++) {\n        if (a + b == 5) {\n            count++;\n        }\n    }\n}', options: ['2', '4', '16', '5'], correctAnswer: 1, explanation: 'The pairs that sum to 5 are (1, 4), (2, 3), (3, 2), and (4, 1), and the nested loops check every ordered pair, so count is 4. Two treats the pairs as unordered, 16 counts every pair checked, and 5 also counts a pair such as (0, 5) that the loops never reach.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'For a positive int n, how many times does count++ execute in the following code segment?\nfor (int i = 0; i < n; i++) {\n    for (int j = 0; j < i; j++) {\n        count++;\n    }\n}', options: ['n(n + 1) / 2', 'n(n - 1) / 2', 'n * n', 'n * (n - 1)'], correctAnswer: 1, explanation: 'The inner loop runs 0, 1, 2, ..., n - 1 times, and that sum is n(n - 1) / 2. n(n + 1) / 2 would need the inner loop to run up to n times, n * n ignores the dependence on i, and n * (n - 1) double-counts.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nString s = "banana";\nint c = 0;\nfor (int i = 0; i < s.length(); i++) {\n    for (int j = i + 1; j < s.length(); j++) {\n        if (s.substring(i, i + 1).equals(s.substring(j, j + 1))) {\n            c++;\n        }\n    }\n}', options: ['4', '3', '8', '15'], correctAnswer: 0, explanation: 'The loops compare every pair of positions with i before j. The three a\'s form 3 pairs and the two n\'s form 1 pair, for 4. Three counts only the a\'s, 8 counts each matching pair twice, and 15 counts every pair of positions whether or not the letters match.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'A loop body uses s.substring(i, i + 1). Which loop header visits every character of the String s from the last character to the first?', options: ['for (int i = s.length(); i > 0; i--)', 'for (int i = s.length() - 1; i > 0; i--)', 'for (int i = s.length() - 1; i >= 0; i--)', 'for (int i = 0; i < s.length(); i++)'], correctAnswer: 2, explanation: 'The last index is s.length() - 1, and the loop must include index 0. Starting at s.length() causes an out-of-bounds substring call, i > 0 skips the first character, and counting up visits the characters in the wrong order.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nfor (int i = 1; i <= 3; i++) {\n    for (int j = 1; j <= 2; j++) {\n        System.out.print(i * j + " ");\n    }\n}', options: ['1 2 3 2 4 6', '1 2 3 4 5 6', '2 4 6 3 6 9', '1 2 2 4 3 6'], correctAnswer: 3, explanation: 'For each i, the inner loop prints i * 1 and then i * 2, giving 1 2, then 2 4, then 3 6. Printing 1 2 3 2 4 6 swaps the roles of the loops, 1 to 6 counts instead of multiplying, and 2 4 6 3 6 9 uses j values of 2 and 3.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'A palindrome check compares s.substring(i, i + 1) with the matching character from the end, for i from 0 while i < s.length() / 2. How many comparisons does it make for a palindrome of length 19 when every pair matches?', options: ['10', '19', '9', '18'], correctAnswer: 2, explanation: '19 / 2 is 9 in integer division, so i takes the values 0 through 8, and the middle character has no partner to compare. Ten rounds up, 19 compares every character, and 18 counts each pair from both ends.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nfor (int i = 0; i < 2; i++) {\n    for (int j = 0; j < 3; j++) {\n        System.out.print(j);\n    }\n}', options: ['001122', '0123', '012', '012012'], correctAnswer: 3, explanation: 'The inner loop prints 012 completely for each of the 2 outer iterations, so 012 appears twice. 001122 prints the outer variable pattern, 0123 runs the inner loop one extra time, and 012 runs the outer loop once.', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'What is the value of r after this code segment executes?\nString s = "abcde";\nString r = "";\nfor (int i = 0; i < s.length(); i += 2) {\n    r = s.substring(i, i + 1) + r;\n}', options: ['"ace"', '"eca"', '"ec"', '"aec"'], correctAnswer: 1, explanation: 'i takes the values 0, 2, and 4, and each new character goes in front of r: "a", then "ca", then "eca". "ace" appends instead of prepending, "ec" leaves out the first character, and "aec" mixes the two orders.', difficulty: 'hard', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },
  { question: 'For n = 10, how many times does process() run in Segment I and in Segment II?\nSegment I:\nfor (int i = 0; i < n; i++) {\n    for (int j = 0; j < n; j++) { process(); }\n}\nSegment II:\nfor (int i = 0; i < n; i++) { process(); }\nfor (int j = 0; j < n; j++) { process(); }', options: ['100 and 20', '20 and 100', '100 and 100', '20 and 20'], correctAnswer: 0, explanation: 'Nested loops multiply, 10 * 10 = 100, while loops placed one after the other add, 10 + 10 = 20. The other pairs either swap the two counts or treat both segments as the same structure.', difficulty: 'medium', domain: 'iteration', topicSlug: 'csa-loops', formSet: 1, part: 1 },
  { question: 'A loop that reverses the String s starts with int i = s.length() - 1 rather than int i = s.length(). Why?', options: ['The loop must skip the first character', 'The last character is one index below the length', 'Strings are stored in reverse order', 'Index s.length() holds a hidden end marker'], correctAnswer: 1, explanation: 'Indexes run from 0 to s.length() - 1, so the last character is at s.length() - 1, and starting at s.length() would make substring(i, i + 1) go out of bounds. The loop still reaches index 0, Strings are stored in normal order, and there is no character at index s.length().', difficulty: 'easy', domain: 'iteration', topicSlug: 'csa-loops', formSet: 2, part: 1 },

  // ── csa-writing-classes (writing-classes) ──
  { question: 'Which of the following is a correct header for a constructor of the class Book?', options: ['public void Book(String title)', 'void public Book(String title)', 'public Book(String title)', 'private book(String title)'], correctAnswer: 2, explanation: 'A constructor has exactly the class name and no return type, not even void. Adding void turns it into an ordinary method, putting void before the access modifier is not valid syntax, and Java names are case-sensitive, so book does not match Book.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'Which instance variable declaration follows the principle of encapsulation?', options: ['private int pages;', 'public int pages;', 'int private pages;', 'public final pages;'], correctAnswer: 0, explanation: 'Encapsulated instance variables are private, so only the class\'s own methods can read or change them. A public variable can be changed directly by any class, the modifier must come before the type, and the last declaration leaves out the type entirely.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'The method public void setRate(double r) { rate = r; } belongs to a class with a private instance variable rate. How is this method best described?', options: ['An accessor', 'A constructor', 'A static method', 'A mutator'], correctAnswer: 3, explanation: 'The method changes the value of an instance variable and returns nothing, which makes it a mutator. An accessor returns a value without changing it, a constructor has no return type and shares the class\'s name, and the method does not use the static keyword.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'What is printed by the following code?\npublic class Plant {\n    private int height;\n    public Plant(int height) {\n        height = height;\n    }\n    public int getHeight() {\n        return height;\n    }\n}\n// in another class\nPlant p = new Plant(12);\nSystem.out.println(p.getHeight());', options: ['12', '0', 'null', 'It does not compile'], correctAnswer: 1, explanation: 'Inside the constructor, height refers to the parameter, so height = height assigns the parameter to itself and the instance variable keeps its default value, 0. Writing this.height = height would store 12. An int field cannot be null, and assigning a variable to itself is legal, so the code compiles.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'The class Box has exactly two constructors, public Box(int w) and public Box(int w, int h). Which statement causes a compile error?', options: ['Box b = new Box();', 'Box b = new Box(3, 4);', 'Box b = new Box(5);', 'Box b = new Box(2 + 1);'], correctAnswer: 0, explanation: 'Because the class defines its own constructors, Java does not supply a no-argument constructor, so new Box() has no match. The other calls match the one-parameter or two-parameter constructor; 2 + 1 is simply an int argument.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'What is printed by the following code?\npublic class Coin {\n    private int value;\n    private int year;\n    public Coin(int v, int y) {\n        value = v;\n        year = y;\n    }\n    public String getLabel() {\n        return year + ": " + value + "c";\n    }\n}\n// in another class\nCoin c = new Coin(25, 1999);\nSystem.out.println("My " + c.getLabel());', options: ['My 25: 1999c', 'My 2024c', 'My 1999: 25c', 'My 1999: 25'], correctAnswer: 2, explanation: 'getLabel builds year, then ": ", then value, then "c", so the line printed is My 1999: 25c. Swapping 25 and 1999 confuses the order of the constructor parameters, 2024c assumes the two ints are added even though a String sits between them, and leaving off the c ignores the last piece of the concatenation.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'A Player object\'s score is 40, and the class contains the method below. After p.setScore(120); p.setScore(-5); p.setScore(75); execute, what does p.getScore() return?\npublic void setScore(int s) {\n    if (s >= 0 && s <= 100) {\n        score = s;\n    }\n}', options: ['120', '-5', '40', '75'], correctAnswer: 3, explanation: 'The mutator ignores values outside 0 to 100, so the calls with 120 and -5 change nothing, and the call with 75 stores 75. Returning 120 or -5 skips the validation, and 40 ignores the last, valid call.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'What is printed by the following code?\npublic class Account {\n    private double balance;\n    public Account(double b) { balance = b; }\n    public void deposit(double amt) { balance += amt; }\n    public double getBalance() { return balance; }\n}\n// in another class\nAccount a = new Account(50.0);\na.deposit(20.0);\na.deposit(-5.0);\nSystem.out.println(a.getBalance());', options: ['70.0', '75.0', '50.0', '65.0'], correctAnswer: 3, explanation: 'The balance starts at 50.0, rises to 70.0, and the deposit of -5.0 lowers it to 65.0, because deposit adds whatever amount it receives. 70.0 ignores the second call, 75.0 adds 5.0 instead of -5.0, and 50.0 ignores both calls.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'The class Thermostat declares private double temp; Code in a different class contains t.temp = 500; where t is a Thermostat. What happens?', options: ['The value of temp becomes 500', 'temp is unchanged at run time', 'It does not compile', 'It throws an exception'], correctAnswer: 2, explanation: 'A private instance variable can be accessed only inside its own class, so the compiler rejects the assignment. The value never changes because the code never runs, and the problem is caught at compile time rather than with an exception.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'What is printed by the following code?\npublic class Box {\n    private int w;\n    public Box(int w) { this.w = w; }\n    public void grow() { w++; }\n    public int getW() { return w; }\n}\n// in another class\nBox a = new Box(3);\nBox b = a;\nb.grow();\na.grow();\nSystem.out.println(a.getW());', options: ['4', '5', '3', '6'], correctAnswer: 1, explanation: 'a and b refer to the same Box object, so both calls to grow change the same w, from 3 to 5. Four treats b as a separate copy, 3 ignores both calls, and 6 counts a third increment that never happens.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'The class Lamp has a private int watts and an accessor getWatts. Its two constructors are shown below. What is printed?\npublic Lamp() { watts = 60; }\npublic Lamp(int w) { watts = w; }\n// in another class\nLamp x = new Lamp();\nLamp y = new Lamp(40);\nSystem.out.println(x.getWatts() + y.getWatts());', options: ['100', '60', '40', '6040'], correctAnswer: 0, explanation: 'x uses the no-argument constructor, so its watts is 60, and y uses the int constructor, so its watts is 40; both accessors return ints, so + adds them to 100. 6040 would need String concatenation, and 60 or 40 alone ignores one of the objects.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'Which statement about constructors is accurate?', options: ['A constructor must have the return type void', 'A constructor is named after its first field', 'A class may have at most one constructor', 'A constructor has no return type, not even void'], correctAnswer: 3, explanation: 'A constructor has the class\'s name and no return type at all. Adding void would make it an ordinary method, constructors are named after the class rather than a field, and a class may overload constructors with different parameter lists.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'What is printed by the following code?\npublic class Counter {\n    private int count = 5;\n    public void add(int count) {\n        count += count;\n    }\n    public int get() { return count; }\n}\n// in another class\nCounter c = new Counter();\nc.add(12);\nSystem.out.println(c.get());', options: ['17', '24', '5', '12'], correctAnswer: 2, explanation: 'Inside add, count names the parameter, so count += count doubles the local parameter to 24 and leaves the instance variable at 5. 17 would need this.count += count, 24 is the parameter\'s value that disappears when the method ends, and 12 is the argument.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },
  { question: 'The class Student has the instance variable private String name; Which accessor method is written correctly?', options: ['public void getName() { return name; }', 'public String getName() { return name; }', 'public String getName() { name; }', 'public String getName() { return; }'], correctAnswer: 1, explanation: 'An accessor returns the field\'s value, so its return type must match String and its body must return name. A void method cannot return a value, a body that is just name; is not a statement and returns nothing, and a bare return; gives a String method no value to return.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 2, part: 1 },
  { question: 'The class Ticket has a private double price that must never be negative. Which mutator best protects the object from invalid data?', options: ['public void setPrice(double p) { if (p >= 0) price = p; }', 'public void setPrice(double p) { price = p; }', 'public double setPrice(double p) { return price; }', 'public void setPrice(double p) { p = price; }'], correctAnswer: 0, explanation: 'Checking the argument before storing it keeps price valid, which is the point of encapsulation. Storing p without a check allows negative prices, returning price changes nothing, and p = price overwrites the parameter instead of the field.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-writing-classes', formSet: 1, part: 1 },

  // ── csa-class-design (writing-classes) ──
  { question: 'What is printed by the following code?\npublic class Ticket {\n    private static int sold = 0;\n    private int id;\n    public Ticket() {\n        sold++;\n        id = sold;\n    }\n    public int getId() { return id; }\n    public static int getSold() { return sold; }\n}\n// in another class\nTicket a = new Ticket();\nTicket b = new Ticket();\nTicket c = new Ticket();\nSystem.out.println(b.getId() + " " + Ticket.getSold());', options: ['2 3', '2 2', '3 3', '1 3'], correctAnswer: 0, explanation: 'sold is static, so all Tickets share one counter that reaches 3; each id copies the counter\'s value when that ticket is built, so b\'s id is 2. Printing 2 2 freezes the shared count at b\'s creation, 3 3 treats id as shared too, and 1 3 gives every object its own counter.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'In the class below, which variable cannot be used at the point marked // here?\npublic class Tally {\n    private int count;\n    public void run(int limit) {\n        int total = 0;\n        for (int i = 0; i < limit; i++) {\n            total += i;\n        }\n        // here\n    }\n}', options: ['The local variable total', 'The loop variable i', 'The method parameter limit', 'The instance variable count'], correctAnswer: 1, explanation: 'A variable declared in a for loop header exists only inside that loop. total is declared in the method body before the loop, limit is a parameter available throughout run, and count is an instance variable available in every instance method of the class.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'The class Stats contains public static double avg(int a, int b). How is this method normally called from another class?', options: ['avg.Stats(4, 6)', 'Stats.avg(4)', 'Stats.avg(4, 6)', 'Stats().avg(4, 6)'], correctAnswer: 2, explanation: 'A static method belongs to the class, so it is called with the class name followed by a dot and the method name. Reversing the names and adding parentheses after the class name are not valid ways to call a method, and passing one argument does not match a method that takes two.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'Consider the class below. Which statement about it is accurate?\npublic class Dog {\n    private String name;\n    public static String describe() {\n        return "Dog " + name;\n    }\n}', options: ['describe returns "Dog null"', 'describe returns "Dog " only', 'describe throws an exception', 'It does not compile'], correctAnswer: 3, explanation: 'A static method is not called on any object, so it cannot refer to the instance variable name directly, and the compiler rejects the method. Since the class never compiles, describe never runs to return a value or throw an exception.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'A class contains both of the following methods. What is printed by System.out.println(area(3) + area(2, 5)); ?\npublic static int area(int s) { return s * s; }\npublic static int area(int w, int h) { return w * h; }', options: ['13', '910', '19', '10'], correctAnswer: 2, explanation: 'The calls match different overloaded methods by their argument lists: area(3) returns 9 and area(2, 5) returns 10, so the sum is 19. Thirteen treats area(3) as 3, 910 joins the results as text even though both are ints, and 10 counts only the second call.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'What does calc() return for a Thing object?\npublic class Thing {\n    private int x = 4;\n    public int calc() {\n        int x = 10;\n        return x + this.x;\n    }\n}', options: ['8', '14', '20', '10'], correctAnswer: 1, explanation: 'The local x, 10, hides the instance variable inside calc, while this.x still names the instance variable, 4, so the sum is 14. Eight uses the instance variable twice, 20 uses the local variable twice, and 10 ignores this.x.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'What is printed by the following code?\npublic class Clicker {\n    private static int total = 0;\n    private int mine = 0;\n    public void click() { mine++; total++; }\n    public int getMine() { return mine; }\n    public static int getTotal() { return total; }\n}\n// in another class\nClicker a = new Clicker();\nClicker b = new Clicker();\na.click();\na.click();\nb.click();\nSystem.out.println(a.getMine() + " " + b.getMine() + " " + Clicker.getTotal());', options: ['2 1 3', '2 1 2', '3 3 3', '2 1 1'], correctAnswer: 0, explanation: 'Each object has its own mine, so a\'s is 2 and b\'s is 1, but total is static and counts all three clicks. Showing a total of 2 or 1 treats total as belonging to one object, and 3 3 3 treats mine as shared.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'What is the result of the following code segment?\nfor (int i = 0; i < 3; i++) {\n    int sq = i * i;\n}\nSystem.out.println(sq);', options: ['It prints 4 after the loop', 'It prints 9 after the loop', 'It prints 0 after the loop', 'It fails to compile'], correctAnswer: 3, explanation: 'sq is declared inside the loop body, so its scope ends at the closing brace, and the println cannot refer to it. If sq were declared before the loop, 4 would print; 9 would need i to reach 3, and 0 is only the first value of sq.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'A method should return the average of the values in an int array and does not use any instance variables. Which header is the best fit?', options: ['public void average(int[] nums)', 'public static int average(double nums)', 'public static double average(int[] nums)', 'public static double average()'], correctAnswer: 2, explanation: 'The method needs the array as a parameter, returns a double average, and uses no object state, so it can be static. A void method cannot return the average, the third header returns an int and takes a single double, and the last header has no way to receive the array.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'Which phrase best describes a static variable?', options: ['One copy shared by all objects of the class', 'A separate copy stored inside each object of the class', 'A variable whose value can never be reassigned', 'A variable visible only inside the method that declares it'], correctAnswer: 0, explanation: 'A static variable belongs to the class, so every object reads and writes the same single copy. A separate copy per object describes an instance variable, a value that cannot be reassigned describes final, and a variable visible in one method describes a local variable.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'What is printed by the following code?\npublic class Temp {\n    private static int count = 0;\n    private int value;\n    public Temp(int v) {\n        value = v;\n        count += v;\n    }\n    public static int getCount() { return count; }\n}\n// in another class\nnew Temp(4);\nTemp t = new Temp(6);\nt = new Temp(1);\nSystem.out.println(Temp.getCount());', options: ['3', '11', '1', '7'], correctAnswer: 1, explanation: 'Every constructor call adds its argument to the shared static count: 4 + 6 + 1 = 11, even for the object never stored in a variable. Three counts objects rather than adding values, 1 assumes reassigning t resets the count, and 7 forgets the first object.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'What is printed by the following code?\npublic static void bump(int n) {\n    n *= 10;\n}\n// in main\nint x = 6;\nbump(x);\nSystem.out.println(x);', options: ['60', '10', '16', '6'], correctAnswer: 3, explanation: 'Java passes a copy of the int value, so changing n inside bump does not affect x. Sixty assumes the change reaches x, 10 is the multiplier, and 16 adds 10 instead of multiplying and also assumes the change reaches x.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'What is printed by the following code?\npublic static void reset(int[] arr) {\n    arr[0] = 0;\n    arr = new int[] {9, 9};\n}\n// in main\nint[] data = {4, 5};\nreset(data);\nSystem.out.println(data[0] + " " + data[1]);', options: ['9 9', '4 5', '0 9', '0 5'], correctAnswer: 3, explanation: 'The parameter receives a copy of the reference, so arr[0] = 0 changes the caller\'s array. Reassigning arr to a new array changes only the parameter, so data still refers to {0, 5}. Printing 9 9 assumes the reassignment reaches data, and 4 5 assumes nothing changes.', difficulty: 'hard', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },
  { question: 'Which pair of method headers cannot both appear in the same class?', options: ['int f(int a) and int f(double x)', 'int f(int a) and double f(int count)', 'int f(int a) and int f()', 'int f(int a) and void g(int a)'], correctAnswer: 1, explanation: 'Overloaded methods must differ in their parameter lists; two methods named f that each take one int differ only in return type, which is not allowed. A different parameter type, an empty parameter list, and a different method name are all legal.', difficulty: 'medium', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 2, part: 1 },
  { question: 'Where can a local variable declared inside a method be used?', options: ['In every method of the class that declares it', 'In any class that creates an object of the class', 'Only in that method, after its declaration', 'Only inside the constructors of the class'], correctAnswer: 2, explanation: 'A local variable\'s scope runs from its declaration to the end of the block that contains it, inside that method only. Other methods cannot see it, other classes cannot reach it, and it is not limited to constructors.', difficulty: 'easy', domain: 'writing-classes', topicSlug: 'csa-class-design', formSet: 1, part: 1 },

  // ── csa-array (arrays) ──
  { question: 'After double[] prices = new double[4]; executes, what is the value of prices[2]?', options: ['0.0', 'null', '0', '4.0'], correctAnswer: 0, explanation: 'A new double array fills every element with the default value 0.0. null is the default only for arrays of objects, 0 is the int default rather than the double one, and 4.0 is the length of the array, not an element.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'Given int[] v = {6, 2, 9, 4}; what is the value of v[v.length - 1]?', options: ['9', '4', '6', '2'], correctAnswer: 1, explanation: 'v.length is 4, so the expression is v[3], the last element, 4. The value 9 is at index 2, 6 is the first element, and 2 is at index 1.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'After int[] a = new int[8]; executes, which indexes can be used with a without an error?', options: ['1 through 8', '0 through 8', '1 through 7', '0 through 7'], correctAnswer: 3, explanation: 'Array indexes start at 0 and end at length - 1, so an array of 8 elements uses 0 through 7. Index 8 is out of bounds, and index 0 is the first valid index, not an error.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nString[] names = new String[3];\nSystem.out.println(names[1]);', options: ['An empty line', '0', 'null', 'It does not compile'], correctAnswer: 2, explanation: 'A new array of objects fills each element with null, and printing a null reference prints null. An empty String would print an empty line, but no String objects exist yet; 0 is the int default, and the code is legal.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'What is the value of avg after this code segment executes?\nint[] s = {7, 8, 10};\nint total = 0;\nfor (int x : s) {\n    total += x;\n}\ndouble avg = total / s.length;', options: ['8.0', '8.333333333333334', '9.0', '25.0'], correctAnswer: 0, explanation: 'total is 25 and s.length is 3, both ints, so the division is integer division, giving 8, which is stored as 8.0. Getting 8.333333333333334 needs a cast to double before dividing, 9.0 assumes rounding, and 25.0 is the total before dividing.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint[] a = {1, 2, 3};\nfor (int x : a) {\n    x += 10;\n}\nfor (int i = 0; i < a.length; i++) {\n    a[i] *= 2;\n}\nSystem.out.println(a[0] + a[2]);', options: ['48', '4', '28', '8'], correctAnswer: 3, explanation: 'The enhanced for loop variable is a copy of each element, so adding 10 to x leaves the array unchanged; the indexed loop then doubles it to {2, 4, 6}, and 2 + 6 is 8. 48 assumes the first loop changed the array, 4 ignores the doubling, and 28 adds 10 to only one element.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nint[] t = {72, 85, 90, 68, 85, 77};\nint c = 0;\nfor (int i = 0; i < t.length; i++) {\n    if (t[i] >= 80) {\n        c++;\n    }\n}', options: ['2', '3', '4', '6'], correctAnswer: 1, explanation: 'The values 85, 90, and 85 meet the condition, so c is 3. Two counts the repeated 85 only once, 4 also counts 77, and 6 is the length of the array.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'What is the value of idx after this code segment executes?\nint[] d = {5, 3, 8, 3, 1, 4};\nint idx = 0;\nfor (int i = 1; i < d.length; i++) {\n    if (d[i] < d[idx]) {\n        idx = i;\n    }\n}', options: ['1', '3', '4', '0'], correctAnswer: 2, explanation: 'The loop tracks the index of the smallest value: it moves to 1 for the first 3, keeps 1 for the second 3 because 3 < 3 is false, and moves to 4 for the 1. The value 1 is the minimum itself, 3 is the index of the second 3, and 0 assumes no update happens.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'A loop body uses arr[i]. Which loop header causes an ArrayIndexOutOfBoundsException?', options: ['for (int i = 0; i <= arr.length; i++)', 'for (int i = 0; i < arr.length; i++)', 'for (int i = 2; i < arr.length; i++)', 'for (int i = 1; i < arr.length; i++)'], correctAnswer: 0, explanation: 'With <=, i eventually equals arr.length, one past the last valid index. The standard forward loop stays within 0 through arr.length - 1, and starting at 1 or 2 only skips elements at the front.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'What is the value of a[4] after this code segment executes?\nint[] a = new int[5];\nfor (int i = 1; i < a.length; i++) {\n    a[i] = a[i - 1] + i;\n}', options: ['15', '6', '4', '10'], correctAnswer: 3, explanation: 'a[0] stays 0, and each element adds its index to the one before it: 1, 3, 6, 10. Fifteen adds 1 through 5, 6 is a[3], and 4 is only the last index.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint[] p = {1, 2, 3};\nint[] q = p;\nq[0] = 5;\np[2] = q[0] + p[1];\nSystem.out.println(q[2]);', options: ['3', '7', '5', '8'], correctAnswer: 1, explanation: 'p and q refer to the same array, so q[0] = 5 is visible through p, and p[2] becomes 5 + 2 = 7, which q[2] also shows. Printing 3 treats q as a separate copy, 5 is q[0], and 8 uses p[1] as 3.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'Which code segment doubles every element of the int array a?', options: ['for (int i = 0; i < a.length; i++) a[i] = a[i] * 2;', 'for (int x : a) x *= 2;', 'for (int i = 0; i < a.length; i++) a[i] = i * 2;', 'for (int i = 1; i <= a.length; i++) a[i] *= 2;'], correctAnswer: 0, explanation: 'An indexed loop over every valid index can change each element in place. The enhanced for loop changes only a copy, a[i] = i * 2 stores doubled indexes rather than doubled values, and starting at 1 with <= skips index 0 and goes out of bounds.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'Which expression gives the number of elements in the int array data?', options: ['data.length()', 'data.size()', 'data.length', 'data.length - 1'], correctAnswer: 2, explanation: 'An array\'s length is a field, written without parentheses. length() is the String method, size() is the ArrayList method, and data.length - 1 is the last valid index rather than the count.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'What is the value of out after this code segment executes?\nString[] w = {"to", "be", "or"};\nString out = "";\nfor (String s : w) {\n    out = s + out;\n}', options: ['"tobeor"', '"orbe"', '"toorbe"', '"orbeto"'], correctAnswer: 3, explanation: 'Each word is placed in front of what has been built so far: "to", then "beto", then "orbeto". "tobeor" appends instead of prepending, "orbe" leaves out the first word, and "toorbe" does not match either order.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },
  { question: 'A student tries to find the largest value in an array. What is the value of max after this code segment executes?\nint[] v = {-4, -9, -2, -7};\nint max = 0;\nfor (int x : v) {\n    if (x > max) {\n        max = x;\n    }\n}', options: ['-2', '0', '-4', '-9'], correctAnswer: 1, explanation: 'Every element is negative, so x > max is never true and max keeps its starting value, 0, which is not in the array. Initializing max to v[0] would give the true largest value, -2; -4 is the first element and -9 is the smallest.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-array', formSet: 1, part: 1 },
  { question: 'The statement for (int x : arr) { x = 0; } leaves the int array arr unchanged. Why?', options: ['An enhanced for loop can only read String arrays', 'The loop never runs when the array holds ints', 'x holds a copy of each element, not the element itself', 'Assigning 0 to an element requires a cast'], correctAnswer: 2, explanation: 'The enhanced for loop copies each element\'s value into x, so assigning to x changes only the copy. Enhanced for loops work on arrays of any type, the loop does run once per element, and assigning 0 to an int needs no cast.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-array', formSet: 2, part: 1 },

  // ── csa-arrays (arrays) ──
  { question: 'Consider the following method. What does find(nums, 7) return when nums is {4, 7, 1, 7}?\npublic static int find(int[] arr, int target) {\n    for (int i = 0; i < arr.length; i++) {\n        if (arr[i] == target) {\n            return i;\n        }\n    }\n    return -1;\n}', options: ['1', '3', '7', '-1'], correctAnswer: 0, explanation: 'The method returns as soon as it finds the target, and the first 7 is at index 1. Index 3 is the second 7, which is never reached, 7 is the value rather than its index, and -1 is returned only when the target is missing.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'The method find(arr, target) performs a linear search, returning the index of the first match or -1 if the target is not found. What does find(nums, 9) return when nums is {2, 4, 6}?', options: ['0', '3', '-1', '2'], correctAnswer: 2, explanation: '9 is not in the array, so the loop finishes and the method returns -1. 0 is a valid index and would wrongly report a match at the start, 3 is the length of the array, and 2 is the last index.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'What are the contents of a after this code segment executes?\nint[] a = {10, 20, 30, 40};\nfor (int i = a.length - 1; i > 0; i--) {\n    a[i] = a[i - 1];\n}\na[0] = 5;', options: ['{5, 10, 10, 10}', '{5, 10, 20, 30}', '{5, 20, 30, 40}', '{10, 10, 10, 10}'], correctAnswer: 1, explanation: 'Working from the end, each element copies its left neighbor, shifting everything right by one and losing the 40; then 5 goes into the front. {5, 10, 10, 10} is what a front-to-back shift produces, {5, 20, 30, 40} only overwrites the first element, and {10, 10, 10, 10} forgets the final assignment.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'A student tries to shift every element one place to the right. What are the contents of a after this code segment executes?\nint[] a = {10, 2, 3, 4};\nfor (int i = 1; i < a.length; i++) {\n    a[i] = a[i - 1];\n}', options: ['{10, 10, 10, 10}', '{10, 10, 2, 3}', '{2, 3, 4, 4}', '{4, 10, 2, 3}'], correctAnswer: 0, explanation: 'Moving front to back, a[1] gets 10, then a[2] copies the new a[1], which is 10, and so on, so every element becomes 10. {10, 10, 2, 3} is the intended result, which requires looping from the end; {2, 3, 4, 4} is a left shift, and {4, 10, 2, 3} is a rotation.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'What are the contents of r after this code segment executes?\nint[] r = {1, 2, 3, 4, 5};\nfor (int i = 0; i < r.length; i++) {\n    int temp = r[i];\n    r[i] = r[r.length - 1 - i];\n    r[r.length - 1 - i] = temp;\n}', options: ['{5, 4, 3, 2, 1}', '{5, 4, 3, 4, 5}', '{1, 2, 3, 2, 1}', '{1, 2, 3, 4, 5}'], correctAnswer: 3, explanation: 'The loop runs over the whole array, so each pair is swapped twice: once on the way to the middle and again on the way back, restoring the original order. Stopping at r.length / 2 would give {5, 4, 3, 2, 1}, and the other results come from copying without a temporary variable.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nint[] v = {3, 3, 5, 5, 5, 2};\nint c = 0;\nfor (int i = 0; i < v.length - 1; i++) {\n    if (v[i] == v[i + 1]) {\n        c++;\n    }\n}', options: ['2', '3', '5', '4'], correctAnswer: 1, explanation: 'The equal adjacent pairs are 3 and 3, the first two 5s, and the last two 5s, so c is 3. Two counts each run of equal values once, 5 counts elements rather than pairs, and 4 counts a pair across the boundary between 5 and 2.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'Selection sort is used to put {4, 8, 3, 7} in ascending order. What does the array look like after the first pass of the outer loop?', options: ['{3, 4, 8, 7}', '{3, 4, 7, 8}', '{8, 4, 3, 7}', '{3, 8, 4, 7}'], correctAnswer: 3, explanation: 'The first pass finds the smallest value, 3, and swaps it with the element at index 0, which is 4. {3, 4, 8, 7} moves 3 to the front by shifting the other elements instead of swapping, {3, 4, 7, 8} is the fully sorted result, and {8, 4, 3, 7} moves the largest value instead.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'Selection sort is used to put {6, 2, 9, 1, 5} in ascending order. What does the array look like after the first two passes of the outer loop?', options: ['{1, 2, 9, 6, 5}', '{1, 2, 6, 9, 5}', '{1, 2, 5, 6, 9}', '{2, 1, 9, 6, 5}'], correctAnswer: 0, explanation: 'Pass one swaps 1 into index 0, giving {1, 2, 9, 6, 5}; pass two finds that 2 is already the smallest remaining value, so it swaps 2 with itself and nothing changes. {1, 2, 6, 9, 5} shifts elements instead of swapping, {1, 2, 5, 6, 9} is the result after a third pass, and {2, 1, 9, 6, 5} places the values in the wrong order.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'How many comparisons does selection sort make, in total, to sort an array of 4 elements?', options: ['16', '12', '6', '10'], correctAnswer: 2, explanation: 'The passes compare 3, 2, and 1 pairs, for 6 comparisons. Sixteen assumes every element is compared with every element, 12 counts each comparison twice, and 10 adds 4 + 3 + 2 + 1 as though there were one more pass.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'Which code segment correctly swaps the values of a[0] and a[1]?', options: ['a[0] = a[1]; a[1] = a[0];', 'int t = a[0]; a[0] = a[1]; a[1] = t;', 'int t = a[0]; a[1] = a[0]; a[0] = t;', 'int t = a[1]; a[0] = a[1]; a[1] = t;'], correctAnswer: 1, explanation: 'Saving a[0] in a temporary variable keeps it from being lost when a[0] is overwritten. Without a temporary variable both elements end up equal, and the other two segments save one value but copy it back to where it came from.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'A program removes the element at index 1 by shifting later elements left. What are the contents of a after this code segment executes?\nint[] a = {8, 6, 4, 2};\nfor (int i = 1; i < a.length - 1; i++) {\n    a[i] = a[i + 1];\n}', options: ['{8, 4, 2, 0}', '{8, 4, 4, 2}', '{4, 2, 2, 2}', '{8, 4, 2, 2}'], correctAnswer: 3, explanation: 'a[1] takes 4 and a[2] takes 2; the loop stops before the last index, so a[3] keeps its old value, 2, and the array size does not change. Arrays never fill a gap with 0 on their own, {8, 4, 4, 2} stops one step early, and {4, 2, 2, 2} starts the shift at index 0.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'A linear search looks for a value in an unsorted array of 40 elements. In the worst case, how many elements does it examine?', options: ['40', '20', '39', '6'], correctAnswer: 0, explanation: 'When the value is missing or in the last position, linear search checks every element, which is 40. Twenty is the average case, 39 stops one element short, and about 6 is the number of steps a binary search needs on sorted data.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'The following method is meant to return true when the array is in strictly increasing order. For which array does it return true even though the array is not in increasing order?\npublic static boolean increasing(int[] a) {\n    for (int i = 0; i < a.length - 1; i++) {\n        if (a[i] < a[i + 1]) {\n            return true;\n        } else {\n            return false;\n        }\n    }\n    return true;\n}', options: ['{15, 1, 2}', '{3, 3, 14}', '{1, 5, 2}', '{19, 8, 7}'], correctAnswer: 2, explanation: 'The method returns during the first comparison, so it only checks the first pair; for {1, 5, 2}, 1 < 5 gives true even though 5 > 2. For the other arrays the first pair is not increasing, so the method correctly returns false.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'A method reverses an array in place by swapping a[i] with a[a.length - 1 - i] while i < a.length / 2. How many swaps does it perform on an array of 18 elements?', options: ['10', '9', '18', '17'], correctAnswer: 1, explanation: '18 / 2 is 9, so i takes the values 0 through 8, and each swap places two elements. Ten runs one pass too many with <=, 18 swaps every element and undoes the work, and 17 loops up to the last index as an ordinary traversal would.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },
  { question: 'What is the value of pos after this code segment executes?\nint[] a = {2, 9, 4, 9, 1};\nint pos = -1;\nfor (int i = 0; i < a.length; i++) {\n    if (a[i] == 9) {\n        pos = i;\n    }\n}', options: ['1', '-1', '9', '3'], correctAnswer: 3, explanation: 'The loop never stops early, so each later match overwrites pos, and the last 9 is at index 3. Index 1 would need the loop to stop at the first match, -1 means no match, and 9 is the value rather than an index.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 1, part: 1 },
  { question: 'When a program inserts a new number by shifting array elements one place to the right, why does the shifting loop start at the end of the array?', options: ['Java loops must count down when they change an array', 'Starting at the end makes the loop run fewer times', 'Starting at the front would overwrite values before they are copied', 'The last element must be removed before any shift'], correctAnswer: 2, explanation: 'Each element copies its left neighbor, so working from the end moves every value before its old position is overwritten; working from the front copies the same value into every later position. Loops may count in either direction, both directions run the same number of times, and arrays have no remove operation.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-arrays', formSet: 2, part: 1 },

  // ── csa-arraylist (arraylist) ──
  { question: 'An ArrayList of String named list contains ["sunrise", "moon", "stars"]. After list.add(1, "comet"); executes, what does list.get(2) return?', options: ['"moon"', '"comet"', '"stars"', '"sunrise"'], correctAnswer: 0, explanation: 'add(1, "comet") inserts at index 1 and shifts the later elements right, giving ["sunrise", "comet", "moon", "stars"], so index 2 holds "moon". "comet" is at index 1, "stars" moved to index 3, and "sunrise" stays at index 0.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'nums is an empty ArrayList of Integer. What are its contents after this code segment executes?\nnums.add(4);\nnums.add(7);\nnums.add(0, 2);\nnums.remove(1);', options: ['[4, 7]', '[2, 4]', '[2, 7]', '[7]'], correctAnswer: 2, explanation: 'The list becomes [4], then [4, 7], then [2, 4, 7] after inserting 2 at index 0; remove(1) deletes the element at index 1, which is 4. [4, 7] removes the first element as though indexes started at 1, [2, 4] removes the last element, and [7] removes two elements.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'scores is an ArrayList of Integer. Which expression gets the element at index 3?', options: ['scores[3]', 'scores.get(3)', 'scores.get[3]', 'scores.get(4)'], correctAnswer: 1, explanation: 'ArrayList elements are read with the get method. Square brackets work only with arrays, get is a method and needs parentheses, and get(4) reads index 4, one position too far.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'roster is an ArrayList of String. Which expression gives the number of elements in roster?', options: ['roster.size()', 'roster.length', 'roster.length()', 'roster.count()'], correctAnswer: 0, explanation: 'ArrayList reports its element count with the size method. length is the array field, length() is the String method, and ArrayList has no count method.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'list is an ArrayList of String containing ["ant", "bee", "cat"]. What is printed by the following code segment?\nString old = list.set(1, "dog");\nSystem.out.println(old + " " + list);', options: ['dog [ant, dog, cat]', 'bee [ant, bee, cat]', 'bee [ant, dog, bee, cat]', 'bee [ant, dog, cat]'], correctAnswer: 3, explanation: 'set replaces the element at index 1 and returns the element it replaced, "bee". Printing dog confuses the returned value with the new value, [ant, bee, cat] ignores the replacement, and the four-element list treats set as an insertion.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'nums is an ArrayList of Integer containing [10, 20, 30, 40]. What is printed by the following code segment?\nint x = nums.remove(2);\nSystem.out.println(x + nums.size());', options: ['34', '23', '303', '33'], correctAnswer: 3, explanation: 'remove(2) deletes and returns the element at index 2, which is 30, leaving 3 elements, and 30 + 3 is 33 because both are ints. 34 uses the size before removal, 23 removes 20 instead, and 303 treats + as concatenation.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'nums is an ArrayList of Integer. Which statement compiles and adds the value 5 to the end of nums?', options: ['nums.add("5");', 'nums.add(5);', 'nums.add(5.0);', 'nums.get(0) = 5;'], correctAnswer: 1, explanation: 'The int 5 is autoboxed to an Integer, so add(5) compiles. A String is not an Integer, a double cannot be boxed into an Integer, and a method call cannot be the target of an assignment.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of Integer containing [3, 8, 2, 7]. What is the value of sum after this code segment executes?\nint sum = 0;\nfor (int i = 1; i < list.size(); i += 2) {\n    sum += list.get(i);\n}', options: ['15', '5', '8', '7'], correctAnswer: 0, explanation: 'i takes the values 1 and 3, so the loop adds 8 and 7, giving 15. Five adds the elements at the even indexes, and 8 or 7 adds only one of the two elements the loop visits.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'list is an ArrayList of String containing ["x", "y", "z"]. Which call throws an IndexOutOfBoundsException?', options: ['list.add(3, "w")', 'list.add(0, "w")', 'list.add(4, "w")', 'list.set(2, "w")'], correctAnswer: 2, explanation: 'add(index, obj) accepts indexes from 0 to size(), so with size 3 the largest legal index is 3, and 4 is out of range. Adding at 3 appends to the end, adding at 0 inserts at the front, and set(2, "w") replaces the last element.', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'Why is an ArrayList that holds whole numbers declared with the element type Integer instead of int?', options: ['Integer values use less memory than int values', 'The int type cannot be used in any list or array', 'An ArrayList can hold only object references', 'The Integer type can also store decimal values'], correctAnswer: 2, explanation: 'ArrayList stores references to objects, so primitives such as int are wrapped in Integer objects, often automatically through autoboxing. Integer objects take more memory than int values, an int array is perfectly legal, and Integer holds only whole numbers.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'list is an ArrayList of String with 5 elements. What is list.size() after these statements execute?\nlist.set(2, "hi");\nlist.add("yo");\nlist.remove(0);', options: ['6', '4', '7', '5'], correctAnswer: 3, explanation: 'set replaces an element without changing the size, add raises the size to 6, and remove lowers it back to 5. Six forgets the removal, 4 treats set as a removal, and 7 treats set as an insertion.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'words is an ArrayList of String containing ["sky", "tree", "sea", "stone"]. What is the value of r after this code segment executes?\nString r = "";\nfor (String w : words) {\n    if (w.length() > 3) {\n        r += w.substring(0, 1);\n    }\n}', options: ['"ts"', '"ss"', '"st"', '"tss"'], correctAnswer: 0, explanation: 'Only "tree" and "stone" are longer than 3 characters, and their first letters, t and s, are added in list order. "ss" uses the 3-letter words, "st" reverses the order, and "tss" adds a letter from a word that fails the condition.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'Which statement about arrays and ArrayLists is accurate?', options: ['An array can change size, but an ArrayList cannot', 'An ArrayList can grow and shrink, but an array cannot', 'Both can grow and shrink as elements are added', 'Neither can change size once it is created'], correctAnswer: 1, explanation: 'An array\'s length is fixed when it is created, while an ArrayList changes size as elements are added and removed. The other statements give arrays a flexible size or take that flexibility away from ArrayList.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of Integer containing [5, 6, 7]. What is printed by the following code segment?\nlist.add(0, list.get(2));\nlist.add(list.size(), list.get(0));\nSystem.out.println(list);', options: ['[7, 5, 6, 7, 5]', '[7, 5, 6, 7]', '[5, 6, 7, 7, 7]', '[7, 5, 6, 7, 7]'], correctAnswer: 3, explanation: 'The first statement inserts 7 at the front, giving [7, 5, 6, 7]. The second appends list.get(0), which is now 7, giving [7, 5, 6, 7, 7]. Appending 5 uses the old first element, the four-element list ignores the second add, and the last list appends instead of inserting at the front.', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },
  { question: 'list is an ArrayList of Integer containing [4, 1, 3]. Which code segment changes it to [4, 3, 1]?', options: ['list.set(1, 1); list.set(2, 3);', 'list.remove(1); list.add(0, 1);', 'list.set(1, list.get(2)); list.set(2, 1);', 'list.set(1, 3); list.set(2, 3);'], correctAnswer: 2, explanation: 'Copying 3 into index 1 gives [4, 3, 3], and setting index 2 to 1 gives [4, 3, 1]. Setting index 1 to 1 and index 2 to 3 leaves the list unchanged as [4, 1, 3], removing and re-adding at the front gives [1, 4, 3], and the last segment ends as [4, 3, 3].', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 1, part: 1 },
  { question: 'nums is an ArrayList of Integer with at least 3 elements. Which statement about the value returned by nums.remove(2) is accurate?', options: ['It is the element that was at index 2 before the removal', 'It is the new size of the list', 'It is true if an element was removed', 'It is the element now at index 2'], correctAnswer: 0, explanation: 'remove(int index) deletes the element at that index and returns it, which is useful for moving it elsewhere. It does not return the size or a boolean, and the element now at index 2 is the one that shifted left into the gap.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist', formSet: 2, part: 1 },

  // ── csa-arraylist-usage (arraylist) ──
  { question: 'list is an ArrayList of String containing ["a", "x", "x", "b"]. What is printed by the following code segment?\nfor (int i = 0; i < list.size(); i++) {\n    if (list.get(i).equals("x")) {\n        list.remove(i);\n    }\n}\nSystem.out.println(list);', options: ['[a, b]', '[a, x, b]', '[a, x, x, b]', '[a, b, b]'], correctAnswer: 1, explanation: 'Removing the "x" at index 1 shifts the second "x" into index 1, but i then moves on to 2, so the second "x" is never checked. [a, b] is what a backward loop would produce, [a, x, x, b] ignores the removal, and [a, b, b] treats removal as copying the next element.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'The body of a loop is if (list.get(i).equals(target)) list.remove(i); Which loop header removes every match without skipping any element?', options: ['for (int i = list.size() - 1; i >= 0; i--)', 'for (int i = 0; i < list.size(); i++)', 'for (int i = list.size(); i >= 0; i--)', 'for (int i = list.size() - 1; i > 0; i--)'], correctAnswer: 0, explanation: 'Going backward, a removal shifts only elements that were already checked, so nothing is skipped. The forward loop skips the element after each removal, starting at list.size() calls get with an out-of-range index, and i > 0 never checks index 0.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'words is an ArrayList of String containing ["map", "road", "sign", "go"], and result is an empty ArrayList of String. What is printed by the following code segment?\nfor (String w : words) {\n    if (w.length() == 4) {\n        result.add(w);\n    }\n}\nSystem.out.println(result);', options: ['[map, go]', '[map, road, sign]', '[road]', '[road, sign]'], correctAnswer: 3, explanation: 'The loop copies only the words with exactly 4 letters into result, in their original order. [map, go] keeps the words that fail the test, [map, road, sign] also keeps a 3-letter word, and [road] stops after the first match.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'nums is an ArrayList of Integer containing [2, 2, 5, 2, 8]. What are its contents after this code segment executes?\nint i = 0;\nwhile (i < nums.size()) {\n    if (nums.get(i) == 2) {\n        nums.remove(i);\n    } else {\n        i++;\n    }\n}', options: ['[2, 5, 8]', '[5, 2, 8]', '[5, 8]', '[2, 5, 2, 8]'], correctAnswer: 2, explanation: 'i advances only when nothing is removed, so after each removal the element that slides into index i is checked too, and every 2 is removed. The other lists keep a 2 that a forward for loop with i++ after every pass might skip.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'a is an ArrayList of Integer containing [1, 2, 3, 4], and b is an empty ArrayList of Integer. What is printed by the following code segment?\nwhile (a.size() > 2) {\n    b.add(a.remove(0));\n}\nSystem.out.println(a + " " + b);', options: ['[1, 2] [3, 4]', '[3, 4] [1, 2]', '[3, 4] [2, 1]', '[4] [1, 2, 3]'], correctAnswer: 1, explanation: 'remove(0) returns the element it removes, so 1 and then 2 move to the end of b, and the loop stops when a has 2 elements. Swapping the lists moves the wrong end, [2, 1] reverses the order of the moves, and [4] [1, 2, 3] runs one extra pass.', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of Integer containing [-3, -8, -1, -6]. What is the value of max after this code segment executes?\nint max = list.get(0);\nfor (int i = 1; i < list.size(); i++) {\n    if (list.get(i) > max) {\n        max = list.get(i);\n    }\n}', options: ['-8', '0', '-3', '-1'], correctAnswer: 3, explanation: 'Starting from the first element, -3, the loop replaces max only with larger values, and -1 is the largest. -8 is the smallest value, 0 is not in the list and would appear only if max started at 0, and -3 is the starting value.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'A forward loop for (int i = 0; i < list.size(); i++) removes elements with list.remove(i). Which statement, placed right after the removal, keeps the loop from skipping elements?', options: ['i++;', 'i--;', 'i = list.size();', 'i += 2;'], correctAnswer: 1, explanation: 'Decreasing i makes the next pass check the same index again, where the next element now sits. i++ and i += 2 skip even more elements, and setting i to list.size() ends the loop after the first removal.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'A program removes elements from an ArrayList inside an enhanced for loop that traverses that same list. What can happen when this code runs?', options: ['It can throw an ArithmeticException', 'It can throw a StringIndexOutOfBoundsException', 'It can throw a ConcurrentModificationException', 'It can throw an ArrayIndexOutOfBoundsException'], correctAnswer: 2, explanation: 'Changing the size of an ArrayList while an enhanced for loop traverses it can throw a ConcurrentModificationException, which is why removal uses an indexed loop. An ArithmeticException comes from dividing an int by zero, a StringIndexOutOfBoundsException from a bad substring index, and an ArrayIndexOutOfBoundsException from a bad index into an array, not an ArrayList.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'nums is an ArrayList of Integer containing [4, 7, 10, 3, 6], and big is an empty ArrayList of Integer. What is printed by the following code segment?\nint total = 0;\nfor (int n : nums) {\n    total += n;\n}\nint avg = total / nums.size();\nfor (int n : nums) {\n    if (n > avg) {\n        big.add(n);\n    }\n}\nSystem.out.println(big);', options: ['[7, 10]', '[7, 10, 6]', '[10]', '[4, 3]'], correctAnswer: 0, explanation: 'The total is 30 and avg is 6, so the values strictly greater than 6, 7 and 10, are added. Including 6 treats > as >=, [10] uses a higher average, and [4, 3] keeps the values below the average.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'nums is an ArrayList of Integer containing [0, 0, 0, 1]. How many elements remain after this code segment executes?\nfor (int i = 0; i < nums.size(); i++) {\n    if (nums.get(i) == 0) {\n        nums.remove(i);\n    }\n}', options: ['1', '2', '3', '0'], correctAnswer: 1, explanation: 'At i = 0 a 0 is removed, leaving [0, 0, 1]; at i = 1 another 0 is removed, leaving [0, 1]; then i is 2, which equals the size, so the loop ends with 2 elements and one 0 left behind. One assumes every 0 is removed, 3 stops after one removal, and 0 removes the 1 too.', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'A method receives an ArrayList of Integer and must return a new list with the negative values left out, without changing the list it receives. Which approach does this?', options: ['Loop forward and remove each negative value from the parameter', 'Loop backward and remove each negative value from the parameter', 'Create an empty list and add each nonnegative value to it', 'Loop through the parameter and set each negative value to zero'], correctAnswer: 2, explanation: 'Building a separate list leaves the original untouched. Removing from the parameter changes the caller\'s list, because the parameter refers to the same object, and setting values to zero changes it as well.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of Integer containing [2, 5, 9, 12], sorted in ascending order. What is printed by the following code segment?\nint v = 7;\nint i = 0;\nwhile (i < list.size() && list.get(i) < v) {\n    i++;\n}\nlist.add(i, v);\nSystem.out.println(list);', options: ['[2, 7, 5, 9, 12]', '[2, 5, 9, 7, 12]', '[2, 5, 9, 12, 7]', '[2, 5, 7, 9, 12]'], correctAnswer: 3, explanation: 'The loop stops at the first element that is not less than 7, which is 9 at index 2, and add(2, 7) inserts there, keeping the list sorted. The other lists place 7 one position too early, one position too late, or at the end.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'A loop removes elements from an ArrayList while traversing from the last index down to 0. After the element at index i is removed, which elements change position?', options: ['Only elements that were already checked', 'Elements not yet checked', 'Every element remaining in the list', 'No element changes position at all'], correctAnswer: 0, explanation: 'Removal shifts the elements after index i one place left, and in a backward traversal those higher indexes were already checked, so no unchecked element moves. That is why backward traversal never skips an element.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of String containing ["yes", "no", "yes", "maybe", "yes"]. What is the value of count after this code segment executes?\nint count = 0;\nfor (String s : list) {\n    if (s.equals("yes")) {\n        count++;\n    }\n}', options: ['2', '5', '1', '3'], correctAnswer: 3, explanation: '"yes" appears at indexes 0, 2, and 4, so count is 3. Two misses one match, 5 counts every element, and 1 counts only the first match.', difficulty: 'easy', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },
  { question: 'list is an ArrayList of Integer containing [4, 4, 6, 6, 6, 9]. What is printed by the following code segment?\nfor (int i = list.size() - 1; i > 0; i--) {\n    if (list.get(i).equals(list.get(i - 1))) {\n        list.remove(i);\n    }\n}\nSystem.out.println(list);', options: ['[4, 6, 6, 9]', '[4, 4, 6, 9]', '[4, 6, 9]', '[4, 4, 6, 6, 9]'], correctAnswer: 2, explanation: 'Working backward, each element equal to the one before it is removed: two of the 6s and one of the 4s, leaving [4, 6, 9]. Keeping an extra 6 or 4 means a duplicate was skipped, which the backward traversal prevents, and [4, 4, 6, 6, 9] stops after the first removal.', difficulty: 'hard', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 1, part: 1 },
  { question: 'list is an ArrayList of String containing ["x", "x", "y"]. A forward for loop that uses i++ removes each "x" it finds, and afterward list is ["x", "y"]. Why was one "x" left behind?', options: ['The second x shifted into index 0, but i had already moved on to 1', 'remove can delete only one element per loop', 'The loop ended before it reached index 1', 'equals does not match the second x'], correctAnswer: 0, explanation: 'Removing index 0 slides the second "x" into index 0, and the next pass checks index 1, which now holds "y", so that "x" is never checked. A loop can remove any number of elements, the loop does reach index 1, and equals compares the text, so it would match.', difficulty: 'medium', domain: 'arraylist', topicSlug: 'csa-arraylist-usage', formSet: 2, part: 1 },

  // ── csa-2d-array (2d-array) ──
  { question: 'After int[][] g = new int[3][5]; executes, what are the values of g.length and g[0].length?', options: ['5 and 3', '3 and 5', '15 and 5', '3 and 15'], correctAnswer: 1, explanation: 'The first size is the number of rows, which is g.length, and the second is the number of columns in each row, which is g[0].length. Swapping them confuses rows with columns, and 15 is the total number of elements, which neither expression gives.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'Given int[][] m = {{4, 7, 1}, {9, 2, 6}}; what is the value of m[1][0]?', options: ['7', '4', '9', '2'], correctAnswer: 2, explanation: 'The first index picks row 1, {9, 2, 6}, and the second picks column 0 of that row, 9. The value 7 is m[0][1], with the indexes swapped, 4 is m[0][0], and 2 is m[1][1].', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'Given int[][] m = {{4, 7, 1}, {9, 2, 6}}; what is the value of m[m.length - 1][m[0].length - 1]?', options: ['6', '1', '2', '9'], correctAnswer: 0, explanation: 'm.length - 1 is 1, the last row, and m[0].length - 1 is 2, the last column, so the expression is m[1][2], which is 6. The value 1 is the last element of the first row, 2 is m[1][1], and 9 is the first element of the last row.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'After boolean[][] seen = new boolean[2][2]; executes, what is the value of seen[1][1]?', options: ['true', 'false', 'null', '0'], correctAnswer: 1, explanation: 'Elements of a new boolean array start as false. true is never a default value, null is the default only for object elements, and 0 is the default for int elements.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] a = {{1, 2}, {3, 4}, {5, 6}};\nfor (int c = 0; c < a[0].length; c++) {\n    for (int r = 0; r < a.length; r++) {\n        System.out.print(a[r][c] + " ");\n    }\n}', options: ['1 2 3 4 5 6', '6 5 4 3 2 1', '2 4 6 1 3 5', '1 3 5 2 4 6'], correctAnswer: 3, explanation: 'The outer loop walks the columns, so this is column-major order: column 0 gives 1 3 5 and column 1 gives 2 4 6. Printing 1 through 6 in order is row-major traversal, and the other two outputs start from the wrong end or the wrong column.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'Which expression accesses the element in row 2, column 0 of the 2D array grid?', options: ['grid[0][2]', 'grid[2, 0]', 'grid[2][0]', 'grid(2)(0)'], correctAnswer: 2, explanation: 'A 2D array element is written with the row index in the first brackets and the column index in the second. grid[0][2] is row 0, column 2, and Java has no comma or parenthesis syntax for array access.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'What is the value of s after this code segment executes?\nint[][] t = {{2, 4}, {6, 8}, {1, 3}};\nint s = 0;\nfor (int[] row : t) {\n    s += row[1];\n}', options: ['15', '9', '24', '14'], correctAnswer: 0, explanation: 'Each row is a 1D array, and row[1] is its second element: 4 + 8 + 3 = 15. Nine adds the first elements, 24 adds every element, and 14 adds only row 1.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'What happens when the following code segment executes?\nint[][] m = new int[2][4];\nfor (int r = 0; r < m[0].length; r++) {\n    for (int c = 0; c < m.length; c++) {\n        m[r][c] = 1;\n    }\n}', options: ['All eight elements are set to 1', 'Only columns 0 and 1 are set to 1', 'Only row 0 is set to 1', 'It throws an exception partway through'], correctAnswer: 3, explanation: 'The loop bounds are swapped: r runs up to 3, but m has only 2 rows, so m[2][0] throws an ArrayIndexOutOfBoundsException after the first two rows are partly filled. The program never finishes, so no complete pattern of 1s results.', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nint[][] g = {{3, 8, 1}, {7, 2, 9}};\nint c = 0;\nfor (int r = 0; r < g.length; r++) {\n    for (int k = 0; k < g[r].length; k++) {\n        if (g[r][k] > r * 5) {\n            c++;\n        }\n    }\n}', options: ['3', '5', '2', '6'], correctAnswer: 1, explanation: 'In row 0 the threshold is 0, so all 3 values count; in row 1 it is 5, so 7 and 9 count. That is 5. Three uses a threshold of 5 for both rows, 2 counts only row 1, and 6 counts every element.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'seats is declared as int[][] seats = new int[5][8]; Which expression gives the total number of elements in seats?', options: ['seats.length + seats[0].length', 'seats.length * seats[0].length', 'seats.length', 'seats[0].length * 2'], correctAnswer: 1, explanation: 'A rectangular 2D array holds rows times columns elements, here 5 * 8 = 40. Adding gives 13, seats.length is only the number of rows, and doubling the column count does not involve the rows.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'What is the value of a[2][1] after this code segment executes?\nint[][] a = new int[3][3];\nfor (int r = 0; r < a.length; r++) {\n    for (int c = 0; c < a[r].length; c++) {\n        a[r][c] = r * 3 + c;\n    }\n}', options: ['5', '6', '8', '7'], correctAnswer: 3, explanation: 'For row 2, column 1, the formula gives 2 * 3 + 1 = 7. Five swaps the row and column, 6 is a[2][0], and 8 is a[2][2].', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] g = {{1, 2}, {3, 4}};\nint[] row = g[0];\nrow[1] = 9;\nSystem.out.println(g[0][1] + g[1][0]);', options: ['12', '5', '13', '10'], correctAnswer: 0, explanation: 'g[0] is a reference to the first row, so row and g[0] are aliases, and row[1] = 9 changes g[0][1]. The sum is 9 + 3 = 12. Five assumes row is a separate copy, 13 adds g[1][1] instead of g[1][0], and 10 adds g[0][0] instead of g[1][0].', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'The body of a loop processes row r of the int[][] m. Which loop header visits every row index exactly once?', options: ['for (int r = 0; r < m[0].length; r++)', 'for (int r = 0; r <= m.length; r++)', 'for (int r = 0; r < m.length; r++)', 'for (int r = 1; r <= m.length; r++)'], correctAnswer: 2, explanation: 'm.length is the number of rows, so r from 0 up to m.length - 1 covers each row once. m[0].length is the number of columns, <= runs one row too far, and starting at 1 with <= skips row 0 and also runs past the last row.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },
  { question: 'What is the value of s after this code segment executes?\nString[][] w = {{"a", "b"}, {"c", "d"}};\nString s = "";\nfor (int c = 1; c >= 0; c--) {\n    for (int r = 0; r < w.length; r++) {\n        s += w[r][c];\n    }\n}', options: ['"bdac"', '"badc"', '"dcba"', '"acbd"'], correctAnswer: 0, explanation: 'The outer loop starts at column 1 and moves left, and the inner loop goes down each column: column 1 gives b then d, and column 0 gives a then c. "badc" walks rows instead of columns, "dcba" reverses everything, and "acbd" visits the columns left to right.', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 2, part: 1 },
  { question: 'grid is a double[][]. Which type belongs in the blank of the header for (___ row : grid)?', options: ['double', 'Double', 'double[]', 'int[]'], correctAnswer: 2, explanation: 'Each element of a 2D array is a 1D array, so the outer enhanced for variable is a double[]. A single double is the element type of the inner loop, Double is the wrapper class for one value, and int[] does not match the element type.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-array', formSet: 1, part: 1 },

  // ── csa-2d-arrays (2d-array) ──
  { question: 'What is the value of s after this code segment executes?\nint[][] m = {{2, 5, 1}, {4, 7, 4}, {9, 0, 3}};\nint s = 0;\nfor (int r = 0; r < m.length; r++) {\n    s += m[r][2];\n}', options: ['12', '15', '35', '8'], correctAnswer: 3, explanation: 'The column index stays at 2 while r changes, so the loop adds the last column: 1 + 4 + 3 = 8. Twelve is the sum of column 1 or of row 2, 15 is the sum of column 0 or of row 1, and 35 adds every element.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'What is the value of sum after this code segment executes?\nint[][] m = {{2, 0, 1}, {3, 5, 7}, {4, 6, 8}};\nint sum = 0;\nfor (int i = 0; i < m.length; i++) {\n    sum += m[i][i];\n}', options: ['10', '15', '13', '18'], correctAnswer: 1, explanation: 'The main diagonal holds m[0][0], m[1][1], and m[2][2], which are 2, 5, and 8, for a sum of 15. Ten is the other diagonal, 1 + 5 + 4, 13 leaves out the first element, and 18 adds the last row.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'A 2D array has 5 rows and 7 columns. How many of its elements are not on the border, meaning not in the first or last row and not in the first or last column?', options: ['20', '35', '24', '15'], correctAnswer: 3, explanation: 'The interior has 5 - 2 = 3 rows and 7 - 2 = 5 columns, so it holds 15 elements. Twenty is the number of border elements, 35 is every element, and 24 counts the border without removing the four corners that were counted twice.', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'A search checks elements in row-major order and stops as soon as it finds the target. How many elements does it check when searching for 1 in {{5, 3}, {8, 1}, {2, 7}}?', options: ['4', '6', '3', '5'], correctAnswer: 0, explanation: 'Row-major order checks 5, 3, 8, and then 1, where the search stops, so it checks 4 elements. Six checks every element, 3 stops before the match, and 5 checks one element past it.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] m = {{-1, 4}, {3, -6}};\nfor (int r = 0; r < m.length; r++) {\n    for (int c = 0; c < m[r].length; c++) {\n        if (m[r][c] < 0) {\n            m[r][c] = -m[r][c] * 2;\n        }\n    }\n}\nSystem.out.println(m[0][0] + m[1][1]);', options: ['7', '-14', '14', '-7'], correctAnswer: 2, explanation: 'Each negative element is replaced by its absolute value doubled: -1 becomes 2 and -6 becomes 12, so the sum is 14. Seven skips the doubling, and the negative answers treat the update as if it kept the sign.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'What is the value of max after this code segment executes?\nint[][] g = {{-5, -2}, {-9, -1}};\nint max = g[0][0];\nfor (int[] row : g) {\n    for (int v : row) {\n        if (v > max) {\n            max = v;\n        }\n    }\n}', options: ['-2', '-1', '-5', '0'], correctAnswer: 1, explanation: 'Starting from an actual element, -5, the loops keep the largest value, -1. -2 is the largest value in the first row only, -5 is the starting value, and 0 would appear only if max started at 0.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] m = {{1, 6, 2}, {4, 0, 5}, {3, 1, 4}};\nint best = 0;\nint bestSum = -1;\nfor (int c = 0; c < m[0].length; c++) {\n    int s = 0;\n    for (int r = 0; r < m.length; r++) {\n        s += m[r][c];\n    }\n    if (s > bestSum) {\n        bestSum = s;\n        best = c;\n    }\n}\nSystem.out.println(best);', options: ['0', '1', '2', '11'], correctAnswer: 2, explanation: 'The column sums are 8, 7, and 11, so the largest belongs to column 2, and best stores that index. Zero is the row with the largest sum, 1 is the column with the smallest sum, and 11 is bestSum rather than best.', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'Which code segment doubles every element of any rectangular int[][] m, whether or not it is square?', options: ['for (int[] row : m) for (int v : row) v *= 2;', 'for (int r = 0; r < m.length; r++) m[r][r] *= 2;', 'for (int r = 0; r < m.length; r++) for (int c = 0; c < m.length; c++) m[r][c] *= 2;', 'for (int r = 0; r < m.length; r++) for (int c = 0; c < m[r].length; c++) m[r][c] *= 2;'], correctAnswer: 3, explanation: 'Indexed loops over every row and every column of that row change each element in place. The enhanced for version changes only copies, the single loop doubles just the diagonal, and using m.length as the column bound skips columns or goes out of range whenever the array is not square.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'What is the value of c after this code segment executes?\nint[][] m = {{5, 3, 4}, {1, 2, 0}};\nint c = 0;\nfor (int r = 0; r < m.length; r++) {\n    for (int k = 0; k < m[r].length - 1; k++) {\n        if (m[r][k] > m[r][k + 1]) {\n            c++;\n        }\n    }\n}', options: ['3', '2', '1', '4'], correctAnswer: 1, explanation: 'The loop compares each element with its right neighbor in the same row: 5 > 3 and 2 > 0 are true, while 3 > 4 and 1 > 2 are false, so c is 2. Three or 1 miscounts one comparison, and 4 counts every comparison made.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'A method sums column 1 of a 2D array. Which index stays fixed while the loop runs?', options: ['The column index, while the row index changes', 'The row index, while the column index keeps changing', 'Both indexes, which stay at 1 for the whole loop', 'Neither index, since both loop variables must change'], correctAnswer: 0, explanation: 'To total one column, the column index stays at 1 and a single loop walks down the rows. Fixing the row would total a row instead, fixing both would read one element, and a single column needs only one changing index.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'Inside nested loops over a square 2D array m with row index r and column index c, which condition is true exactly for the elements on the main diagonal?', options: ['r + c == m.length - 1', 'r == c', 'r == 0 || c == 0', 'r - c == 1'], correctAnswer: 1, explanation: 'Main-diagonal elements run from the top-left to the bottom-right corner, where the row and column indexes match. r + c == m.length - 1 describes the other diagonal, the third condition picks the first row and first column, and r - c == 1 picks the elements just below the diagonal.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'What is the value of sum after this code segment executes?\nint[][] m = {{1, 1, 1, 1}, {1, 5, 6, 1}, {1, 1, 1, 1}};\nint sum = 0;\nfor (int r = 0; r < m.length; r++) {\n    for (int c = 0; c < m[r].length; c++) {\n        if (r == 0 || r == m.length - 1 || c == 0 || c == m[r].length - 1) {\n            sum += m[r][c];\n        }\n    }\n}', options: ['21', '11', '14', '10'], correctAnswer: 3, explanation: 'The condition selects the border: 4 elements in each of the top and bottom rows plus the first and last elements of the middle row, 10 elements that are all 1. Twenty-one is the sum of every element, 11 is the interior sum, and 14 counts the corners twice.', difficulty: 'hard', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'The following method is called on the array {{1, -1, 2}, {3, -3, 0}, {0, 0, 0}}. How many rows does it finish summing before it returns?\npublic static boolean zeroRow(int[][] m) {\n    for (int[] row : m) {\n        int s = 0;\n        for (int v : row) {\n            s += v;\n        }\n        if (s == 0) {\n            return true;\n        }\n    }\n    return false;\n}', options: ['2', '3', '1', '0'], correctAnswer: 0, explanation: 'The first row sums to 2, so the loop continues; the second row sums to 0, so the method returns true right away and never reaches the third row. Three assumes every row is processed, and 1 or 0 stops before the row that sums to zero.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] a = {{1, 2, 3}, {4, 5, 6}};\nint[][] b = new int[3][2];\nfor (int r = 0; r < 2; r++) {\n    for (int c = 0; c < 3; c++) {\n        b[c][r] = a[r][c];\n    }\n}\nSystem.out.println(b[2][0] + " " + b[0][1]);', options: ['4 3', '2 4', '3 4', '3 2'], correctAnswer: 2, explanation: 'Each element moves to the position with its indexes swapped, so b[2][0] is a[0][2], which is 3, and b[0][1] is a[1][0], which is 4. The other pairs read a without swapping the indexes or swap only one of them.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },
  { question: 'What is printed by the following code segment?\nint[][] s = {{80, 90}, {70, 75}, {100, 60}};\ndouble[] avg = new double[s.length];\nfor (int r = 0; r < s.length; r++) {\n    avg[r] = (s[r][0] + s[r][1]) / 2;\n}\nSystem.out.println(avg[1]);', options: ['72.5', '72', '145.0', '72.0'], correctAnswer: 3, explanation: 'Row 1 sums to 145, and 145 / 2 is integer division, giving 72, which is stored as 72.0 in the double array. 72.5 needs a double operand, such as 2.0, 72 ignores that the array holds doubles, and 145.0 skips the division.', difficulty: 'medium', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 1, part: 1 },
  { question: 'A method sums the last column of a rectangular int[][] m. Which expression gives the index of that column?', options: ['m[0].length - 1', 'm.length - 1', 'm[0].length', 'm.length'], correctAnswer: 0, explanation: 'm[0].length is the number of columns, and indexes stop one below the count, so the last column is m[0].length - 1. m.length - 1 is the index of the last row, m[0].length is one past the last column, and m.length is the number of rows.', difficulty: 'easy', domain: '2d-array', topicSlug: 'csa-2d-arrays', formSet: 2, part: 1 },

  // ── csa-recursive-methods (arrays) ──
  { question: 'In a recursive method, what is the base case?', options: ['A branch that returns a result without calling the method again', 'A branch that calls the method again on a smaller argument', 'A branch that runs first every time the method is called', 'A branch that sets up the argument for the very first call'], correctAnswer: 0, explanation: 'The base case is the branch that answers directly without calling the method again, which is what stops the recursion. Calling the method again on a smaller argument is the recursive case, the base case is not necessarily the code that runs first, and the original argument is supplied by the caller rather than by a branch of the method.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 1 },
  { question: 'Consider the following method.\npublic static int sumDown(int n)\n{\n    if (n == 10)\n    {\n        return 0;\n    }\n    return n + sumDown(n - 1);\n}\nWhich best describes the result of the call sumDown(4)?', options: ['The base case is never reached, so the stack overflows', 'It returns 0 because the base case is eventually reached', 'It returns 10, the result of adding 4 + 3 + 2 + 1 together', 'It does not compile because 10 is never passed as an argument'], correctAnswer: 0, explanation: 'Starting at 4 and subtracting 1 each call moves n away from 10, so the base case is never reached and the program throws a StackOverflowError. The base case is never reached, so it cannot return 0, and adding 4 + 3 + 2 + 1 would need a base case at or below 0. The code compiles, because the compiler does not check whether a base case is reachable.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 1 },
  { question: 'Consider the following method.\npublic static void show(int n)\n{\n    if (n > 0)\n    {\n        show(n - 1);\n        System.out.print(n + " ");\n    }\n}\nWhat is printed by the call show(3)?', options: ['3 2 1 0', '3 2 1', '0 1 2 3', '1 2 3'], correctAnswer: 3, explanation: 'The print comes after the recursive call, so each call waits until the deeper calls finish, and the smallest n prints first: 1 2 3. Printing 3 2 1 would require the print before the call, and 0 is never printed because show(0) skips the body.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 2 },
  { question: 'Consider the following method.\npublic static void echo(int n)\n{\n    if (n == 0)\n    {\n        return;\n    }\n    System.out.print(n);\n    echo(n - 1);\n    System.out.print(n);\n}\nWhat is printed by the call echo(3)?', options: ['123321', '321123', '321321', '3210123'], correctAnswer: 1, explanation: 'The first print runs on the way down, printing 3, 2, 1; the second print runs on the way back up, after each deeper call returns, printing 1, 2, 3. The base case returns before printing, so 0 never appears, and the output is not repeated in the same order because the second prints happen in reverse.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 2 },
  { question: 'Consider the following method.\npublic static int total(int n)\n{\n    if (n <= 0)\n    {\n        return 0;\n    }\n    return n + total(n - 3);\n}\nWhat value is returned by the call total(10)?', options: ['21', '55', '22', '10'], correctAnswer: 2, explanation: 'The calls add 10 + 7 + 4 + 1 and then total(-2) returns 0, giving 22. Stopping at 21 leaves out the 1, 55 is the sum of every integer from 1 to 10, and 10 is only the first term.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 2 },
  { question: 'Consider the following method.\npublic static int total(int n)\n{\n    if (n <= 0)\n    {\n        return 0;\n    }\n    return n + total(n - 3);\n}\nHow many calls to total are made when total(7) is evaluated, including the original call?', options: ['3', '7', '2', '4'], correctAnswer: 3, explanation: 'The calls are total(7), total(4), total(1) and total(-2), and the last one hits the base case, so there are 4 calls. Three calls leaves out the base-case call, 7 assumes n drops by 1 each time, and 2 counts only the calls before n drops below 4.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 2 },
  { question: 'Consider the following method.\npublic static int rec(int n)\n{\n    if (n == 0)\n    {\n        return 1;\n    }\n    return 2 * rec(n - 1);\n}\nAssume n >= 0. Which code segment stores the same value in r that rec(n) returns?', options: ['int r = 0;\nfor (int k = 1; k <= n; k++) { r *= 2; }', 'int r = 1;\nfor (int k = 1; k <= n; k++) { r += 2; }', 'int r = 2;\nfor (int k = 0; k <= n; k++) { r *= 2; }', 'int r = 1;\nfor (int k = 1; k <= n; k++) { r *= 2; }'], correctAnswer: 3, explanation: 'rec(n) returns 2 multiplied by itself n times, starting from 1, and the loop that starts r at 1 and doubles it n times matches. Starting r at 0 leaves it 0 forever, adding 2 each pass gives 1 + 2n, and starting at 2 with n + 1 doublings gives four times too much.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 3 },
  { question: 'A recursive method and a loop both compute the same sum, and the recursive version makes n nested calls before any of them returns. Compared with the loop, the recursive version typically', options: ['uses more memory, as each pending call keeps a frame', 'uses less memory, as no loop counter has to be stored', 'runs faster, as the stack replaces repeated comparisons', 'solves more problems, as loops cannot express repetition'], correctAnswer: 0, explanation: 'Every unfinished recursive call keeps its own stack frame with its parameters until the base case returns, so recursion usually uses more memory than a loop. The frames cost more than one loop counter, recursion is usually not faster, and any loop can be rewritten recursively and vice versa.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 3 },
  { question: 'Consider the following method.\npublic static String mix(String s)\n{\n    if (s.length() <= 1)\n    {\n        return s;\n    }\n    return s.substring(s.length() - 1) + mix(s.substring(0, s.length() - 1));\n}\nWhat value is returned by the call mix("code")?', options: ['"code"', '"ecod"', '"edoc"', '"c"'], correctAnswer: 2, explanation: 'Each call puts the last character first and recurses on everything before it: "e" + mix("cod") = "e" + "d" + mix("co") = "e" + "d" + "o" + "c", which is "edoc". Returning "code" ignores the recursion, "ecod" moves only one character, and "c" is just the base case\'s value rather than the whole result.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 4 },
  { question: 'Consider the following method.\npublic static String keep(String s)\n{\n    if (s.length() == 0)\n    {\n        return "";\n    }\n    String first = s.substring(0, 1);\n    if (first.equals("x"))\n    {\n        return keep(s.substring(1));\n    }\n    return first + keep(s.substring(1));\n}\nWhat value is returned by the call keep("axbxc")?', options: ['"xx"', '"cba"', '"axbxc"', '"abc"'], correctAnswer: 3, explanation: 'Every call removes the first character; an "x" is dropped and any other character is kept in front of the result of the rest, so the method returns "abc". "xx" keeps only the dropped characters, "cba" reverses the order, and "axbxc" ignores the test on "x".', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 4 },
  { question: 'Consider the following incomplete method, which is intended to return the number of characters in s.\npublic static int len(String s)\n{\n    /* missing base case */\n    return 1 + len(s.substring(1));\n}\nWhich replacement for /* missing base case */ makes len work for every String s, including ""?', options: ['if (s.length() <= 1) return 0;', 'if (s.length() == 1) return 0;', 'if (s.length() == 0) return 1;', 'if (s.length() == 0) return 0;'], correctAnswer: 3, explanation: 'The empty string has 0 characters, and stopping there means each nonempty call adds 1 for its first character. Returning 0 at length 1 undercounts and lets len("") call substring(1) on an empty string, returning 1 at the empty string counts one character too many, and testing length <= 1 returns 0 for a one-character string.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 4 },
  { question: 'Consider the following method.\npublic static int t(int n)\n{\n    if (n <= 1)\n    {\n        return 1;\n    }\n    return t(n - 1) + t(n - 2);\n}\nWhat value is returned by the call t(6)?', options: ['8', '13', '6', '5'], correctAnswer: 1, explanation: 'Building up from the base cases, t(0) and t(1) are 1, so t(2) = 2, t(3) = 3, t(4) = 5, t(5) = 8 and t(6) = 13. The value 8 is t(5) and 5 is t(4), one or two steps short, and 6 assumes the method simply returns its argument.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 5 },
  { question: 'Consider the following method.\npublic static int tri(int n)\n{\n    if (n <= 0)\n    {\n        return 1;\n    }\n    return tri(n - 1) + tri(n - 1);\n}\nHow many calls to tri are made when tri(3) is evaluated, including the original call?', options: ['8', '15', '7', '4'], correctAnswer: 1, explanation: 'Each call above the base case makes two more calls, so there are 1 + 2 + 4 + 8 = 15 calls in the call tree. The value 8 is what tri(3) returns rather than the number of calls, 7 leaves out the base-case calls, and 4 counts one call per level.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 5 },
  { question: 'The recursive Fibonacci method fib(n), which returns fib(n - 1) + fib(n - 2), becomes very slow as n grows. What is the main reason?', options: ['It recomputes the same smaller values in many separate branches', 'It must copy its entire argument each time a call is made', 'It needs a second base case, which doubles every call\'s work', 'Its two recursive calls run at once and compete for memory'], correctAnswer: 0, explanation: 'Because each call branches into two calls, the call tree computes the same subproblems, such as fib(2), many times over. An int argument is cheap to pass, the second base case only stops the recursion, and the two calls run one after the other rather than at the same time.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 5 },
  { question: 'Consider the following method.\npublic static int countPos(int[] a, int i)\n{\n    if (i == a.length)\n    {\n        return 0;\n    }\n    if (a[i] > 0)\n    {\n        return 1 + countPos(a, i + 1);\n    }\n    return countPos(a, i + 1);\n}\nint[] nums = {3, -1, 0, 5, -2};\nWhat value is returned by the call countPos(nums, 1)?', options: ['2', '3', '1', '0'], correctAnswer: 2, explanation: 'Starting at index 1, the method checks -1, 0, 5 and -2, and only 5 is positive, so it returns 1. Returning 2 also counts the 3 at index 0, which the call skips, 3 also treats 0 as positive, and 0 misses the 5.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 6 },
  { question: 'Consider the following method, which is intended to return the sum of a[i] through the end of the array.\npublic static int sumFrom(int[] a, int i)\n{\n    if (i > a.length)\n    {\n        return 0;\n    }\n    return a[i] + sumFrom(a, i + 1);\n}\nWhich best describes the result of the call sumFrom(arr, 0) for a nonempty array arr?', options: ['An ArrayIndexOutOfBoundsException occurs once i passes the end', 'It returns the correct sum, since the base case returns 0 at the end', 'A StackOverflowError occurs, since i never moves toward the base case', 'It returns the sum of all array elements but the one at the last index'], correctAnswer: 0, explanation: 'When i reaches a.length the test i > a.length is still false, so the method evaluates a[a.length], which is out of bounds. The base case should test i == a.length; i does move toward it, so there is no StackOverflowError, and the last element is added before the exception occurs.', difficulty: 'hard', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 6 },
  { question: 'Consider the following method.\npublic static int addUp(int n)\n{\n    if (n == 0)\n    {\n        return 0;\n    }\n    addUp(n - 1);\n    return n;\n}\nWhat value is returned by the call addUp(4)?', options: ['10', '4', '14', '24'], correctAnswer: 1, explanation: 'The recursive call runs, but its result is thrown away, so each call simply returns its own n and addUp(4) returns 4. The value 10 would require return n + addUp(n - 1), 24 is 4 factorial, and 14 adds the results incorrectly.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 6 },
  { question: 'Consider the following method.\npublic static int digits(int n)\n{\n    if (n < 10)\n    {\n        return 1;\n    }\n    return 1 + digits(n / 10);\n}\nWhat value is returned by the call digits(40213)?', options: ['4', '5', '6', '1'], correctAnswer: 1, explanation: 'Integer division by 10 drops the last digit: 40213, 4021, 402, 40, 4. The last call returns 1 and each of the four calls above it adds 1, giving 5, the number of digits. Four forgets the base case\'s own 1, 6 counts one call too many, and 1 is only the value the base case returns.', difficulty: 'medium', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 2, part: 7 },
  { question: 'Consider the following method.\npublic static int shift(int a, int b)\n{\n    if (b == 0)\n    {\n        return a;\n    }\n    return shift(a + 1, b - 1);\n}\nWhat value is returned by the call shift(3, 4)?', options: ['4', '12', '7', '3'], correctAnswer: 2, explanation: 'Each call moves 1 from b to a, so after four calls b is 0 and a is 7, which the base case returns. The value 3 is the original a, 4 is the original b, and 12 multiplies the arguments instead of adding them.', difficulty: 'easy', domain: 'arrays', topicSlug: 'csa-recursive-methods', formSet: 1, part: 7 },
]


export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string }[] {
  let pool = csaQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
